        // ── Lifecycle ────────────────────────────────────────────────────────────────────

        public static void Init()
        {
            if (_initialized) return;
            EventBus.EntityDestroyed += ForgetEntity;
            // Re-attach rigid/node animation players after a scene loads (entities exist + the
            // NodeAnimationRegistry has been repopulated by the asset/scene preloads).
            EventBus.SceneLoaded += AttachSceneNodeAnimations;
            _texCache.Init();
            _shaderCache.Init();
            _shadowAtlas.Init();
            _cubeShadows.Init();
            _shadowPass.Init();
            _shadowPass.Resize(_shadowAtlas.SliceSize, _cubeShadows.FaceSize);   // a size set before Init (G8.5)
            _shadowDebugPass.Init();
            _tonemapPass.Init();
            _skyboxPass.Init();
            _screenCopyPass.Init();
            _screenSampler = sg_make_sampler(new sg_sampler_desc
            {
                min_filter = sg_filter.SG_FILTER_LINEAR,
                mag_filter = sg_filter.SG_FILTER_LINEAR,
                wrap_u = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                wrap_v = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                label = "transmission-screen-sampler"
            });
            _shadowSampler = sg_make_sampler(new sg_sampler_desc
            {
                min_filter = sg_filter.SG_FILTER_NEAREST,
                mag_filter = sg_filter.SG_FILTER_NEAREST,
                compare = sg_compare_func.SG_COMPAREFUNC_LESS_EQUAL,
                wrap_u = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                wrap_v = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                label = "shadow-atlas-sampler"
            });
            _cubeShadowSampler = sg_make_sampler(new sg_sampler_desc
            {
                min_filter = sg_filter.SG_FILTER_NEAREST,
                mag_filter = sg_filter.SG_FILTER_NEAREST,
                compare = sg_compare_func.SG_COMPAREFUNC_LESS_EQUAL,
                wrap_u = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                wrap_v = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                label = "cube-shadow-array-sampler"
            });
            _jointSampler = sg_make_sampler(new sg_sampler_desc
            {
                min_filter    = sg_filter.SG_FILTER_NEAREST,
                mag_filter    = sg_filter.SG_FILTER_NEAREST,
                mipmap_filter = sg_filter.SG_FILTER_NEAREST,
                wrap_u = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                wrap_v = sg_wrap.SG_WRAP_CLAMP_TO_EDGE,
                label = "joint-matrix-sampler"
            });
            _initialized = true;

            // Build the default environment (cubemap from "skyboxes/skybox", procedural
            // fallback if the faces are missing). The editor overrides this with the
            // project's persisted EnvironmentSettings once a project is open.
            ApplyEnvironment(new EnvironmentSettings());
        }

        public static void Shutdown()
        {
            if (!_initialized) return;
            EventBus.EntityDestroyed -= ForgetEntity;
            EventBus.SceneLoaded -= AttachSceneNodeAnimations;
            _initialized = false;
            Text3DRenderer.Shutdown();
            ScriptLinesRenderer.Shutdown();
            _clusterData?.Dispose();
            _clusterData = null;
            _instanceBuf.Dispose();
            Sprites2D.SpriteRenderSystem.Shutdown();
            _transmissionInstanceBuf.Dispose();
            _screenCopyPass.Shutdown();
            DestroyScreenCopy();
            if (_screenSampler.id != 0) { sg_destroy_sampler(_screenSampler); _screenSampler = default; }
            _matReg.Shutdown();
            _meshReg.Shutdown();
            _texCache.Shutdown();
            _shadowPass.Shutdown();
            _shadowDebugPass.Shutdown();
            _tonemapPass.Shutdown();
            _skyboxPass.Shutdown();
            _cubeShadows.Shutdown();
            _shadowAtlas.Shutdown();
            _environment?.Dispose();
            _environment = null;
            if (_shadowSampler.id != 0)
            {
                sg_destroy_sampler(_shadowSampler);
                _shadowSampler = default;
            }
            if (_cubeShadowSampler.id != 0)
            {
                sg_destroy_sampler(_cubeShadowSampler);
                _cubeShadowSampler = default;
            }
            if (_jointSampler.id != 0)
            {
                sg_destroy_sampler(_jointSampler);
                _jointSampler = default;
            }
            _shaderCache.Dispose();
        }

        // ── View management ──────────────────────────────────────────────────────────────

        public static int RegisterView(RenderView view)
        {
            for (int i = 0; i < _views.Length; i++)
                if (_views[i] == null) { _views[i] = view; return i; }
            throw new InvalidOperationException("Maximum views exceeded.");
        }

        public static void UnregisterView(int viewIndex)
        {
            if ((uint)viewIndex < (uint)_views.Length) _views[viewIndex] = null;
        }

        // ── Registry accessors (for editor tooling) ───────────────────────────────────────

        public static MeshRegistry     Meshes    => _meshReg;
        public static MaterialRegistry Materials => _matReg;
        public static TextureCache     Textures  => _texCache;

        /// <summary>
        /// Imports a glTF/GLB model from the current project's Assets folder (cross-platform, via
        /// SFilesystem). Registers its meshes, PBR materials, and textures, then builds the ECS node
        /// hierarchy under a single container entity. Asynchronous (external .bin/textures are
        /// fetched first); <paramref name="onComplete"/> fires on the main thread with the container
        /// entity, or null on failure. Skinning is not yet wired — skinned models import in bind pose.
        /// </summary>
        public static void ImportGltfAsync(string assetsRelativePath, Action<Entity?>? onComplete = null)
        {
            if (!_initialized) { onComplete?.Invoke(null); return; }
            GameEditor.Framework.Renderer.Server.Assets.GltfImporter.ImportAsync(
                assetsRelativePath, _meshReg, _matReg, _texCache, ECSWorld.Instance, onComplete);
        }

        /// <summary>
        /// Re-registers a glTF/GLB's meshes, materials, and textures WITHOUT creating entities —
        /// used on scene reload to re-populate resources referenced by already-deserialized
        /// MeshRenderers (mesh keys "&lt;file&gt;#m{i}p{j}", material keys "&lt;file&gt;#mat{i}").
        /// </summary>
        public static void PreloadGltfAsync(string assetsRelativePath, Action? onComplete = null)
        {
            if (!_initialized) { onComplete?.Invoke(); return; }
            // After the preload registers resources (incl. node-animation clips), re-attach node
            // players — covers a glTF whose preload finishes AFTER the SceneLoaded hook already ran.
            GameEditor.Framework.Renderer.Server.Assets.GltfImporter.PreloadAsync(
                assetsRelativePath, _meshReg, _matReg, _texCache, ECSWorld.Instance,
                () => { onComplete?.Invoke(); AttachSceneNodeAnimations(); });
        }

        /// <summary>
        /// Reads a glTF/GLB again and replaces, key for key, the meshes, materials and textures loaded from it
        /// (<see cref="GameEditor.Framework.Assets.AssetLibrary.ReimportGltf"/>). <paramref name="onComplete"/>:
        /// whether the file was read, and the mesh keys it no longer has.
        /// </summary>
        public static void ReimportGltfAsync(string assetsRelativePath, Action<bool, IReadOnlyList<string>>? onComplete = null)
        {
            if (!_initialized) { onComplete?.Invoke(false, Array.Empty<string>()); return; }
            GameEditor.Framework.Renderer.Server.Assets.GltfImporter.ReimportAsync(
                assetsRelativePath, _meshReg, _matReg, _texCache, ECSWorld.Instance,
                (ok, lost) => { onComplete?.Invoke(ok, lost); AttachSceneNodeAnimations(); });
        }

        // ── Frame loop ───────────────────────────────────────────────────────────────────

        public static void BeginFrame()
        {
            if (!_initialized) return;
            _instanceBuf.BeginFrame();
            Sprites2D.SpriteRenderSystem.BeginFrame();
            _skinnedInstanceBuf.BeginFrame();
            _transmissionInstanceBuf.BeginFrame();
            _animationFrame++;
            // Advance rigid/node animations (e.g. watch hands) into their entity Transforms BEFORE
            // SubmitView reads them. Once per CPU frame regardless of view count.
            UpdateNodeAnimations();
            Text3DRenderer.Prepare(ECSWorld.Instance);   // G8.4: the texts that changed, drawn into their textures (no pass open)
            _lightBuf.Reset();
            _stats.Reset();
            _drawCount = 0;
            FrameProfiler.BeginFrame();
        }

        public static void RenderShadowMaps(in Matrix4x4 viewProj, CsmCamera? csm = null)
        {
            if (!_initialized) return;

            // Advance skinned animators BEFORE the shadow pass so skinned casters write the current
            // pose into the shadow maps; the color pass (SubmitView) then reads the same pose.
            UpdateSkinnedAnimators(ECSWorld.Instance);

            FrameProfiler.Begin(FrameProfiler.Zone.ShadowPass);
            CollectLightsAndShadows(ECSWorld.Instance, in viewProj, renderShadowPasses: true, csm, forDrawing: false);
            FrameProfiler.End(FrameProfiler.Zone.ShadowPass);
        }

        /// <summary>
        /// Applies the HDR tonemap pass using the provided HDR color image.
        /// Must be called inside an active swapchain <c>sg_begin_pass / sg_end_pass</c> block,
        /// after all geometry and post-process passes have written to the HDR render target.
        /// </summary>
        /// <param name="hdrColorView">sg_view for the RGBA16F HDR offscreen color attachment.</param>
        /// <param name="exposure">Linear exposure multiplier (default 1.0).</param>
        /// <param name="tonemapType">
        ///   0 = Linear, 1 = ACES Narkowicz, 2 = ACES Hill, 3 = KHR PBR Neutral (default 1).
        /// </param>
        public static void RenderTonemapPass(sg_view hdrColorView, float exposure = 1.0f, int tonemapType = 1)
        {
            if (!_initialized) return;
            _tonemapPass.Render(hdrColorView, exposure, tonemapType);
        }

        /// <summary>
        /// Blits a single-sampled scene texture into the active SWAPCHAIN pass (fullscreen copy,
        /// swapchain-format pipeline). For standalone apps that render the 3D scene to an offscreen
        /// target — required so the transmission/refraction pass can run (it samples a copy of the
        /// opaque scene, which the swapchain backbuffer cannot provide). Call inside the swapchain
        /// <c>sg_begin_pass / sg_end_pass</c>; draw 2D/UI overlays after it.
        /// </summary>
        public static void BlitToSwapchain(sg_view sceneColorView)
        {
            if (!_initialized) return;
            _screenCopyPass.RenderToSwapchain(sceneColorView);
        }

        /// <summary>
        /// True when an <b>active and visible</b> mesh actually uses a transmissive
        /// (KHR_materials_transmission) material this frame — i.e. the screen-space refraction path is
        /// needed. A standalone host renders straight to the swapchain (cheapest) when false, and only
        /// switches to the offscreen-target + <see cref="RenderTransmission"/> + <see cref="BlitToSwapchain"/>
        /// path when true, avoiding a redundant full-screen copy on transmission-free frames (mobile win).
        /// <para>
        /// Mirrors <see cref="SubmitView"/>'s per-entity gating (Active + Visible + transmissive material),
        /// so disabling/hiding every glass object correctly flips this to false. The cheap
        /// <see cref="MaterialRegistry.AnyTransmissive"/> registry check is a fast-out: projects with no
        /// transmissive material registered at all skip the per-entity scan entirely.
        /// </para>
        /// </summary>
        public static bool SceneNeedsTransmission
        {
            get
            {
                if (!_initialized || !_matReg.AnyTransmissive) return false;
                var world = ECSWorld.Instance;
                foreach (var row in world.Query<ActiveFlag, MeshRenderer, Transform>()
                                         .Enumerate<ActiveFlag, MeshRenderer, Transform>())
                {
                    if (!row.Item1.Value.Active) continue;
                    ref readonly var mr = ref row.Item2.Value;
                    if (!mr.Visible) continue;
                    if (string.IsNullOrEmpty(mr.MaterialPath) ||
                        string.Equals(mr.MaterialPath, MeshRenderer.NoMaterialSentinel, StringComparison.Ordinal))
                        continue;
                    ushort matId = _matReg.GetIdByKey(mr.MaterialPath);
                    if (matId == 0) matId = _matReg.GetFirstIdByMtlFile(mr.MaterialPath);
                    if (_matReg.GetById(matId) is PbrMaterial { IsTransmissive: true }) return true;
                }
                return false;
            }
        }

        /// <summary>
        /// How many shader families (a shader and its pipelines) have been made: each is made by the first draw that
        /// needs it, so a scene with no meshes makes none. <see cref="ShaderVariantCache.LowTier"/> tells which kind.
        /// </summary>
        public static int ShaderFamiliesMade => _shaderCache.FamiliesMade;
        /// <summary>The shader families made so far, by name ("pbr", "pbr-clustered", ...).</summary>
        public static IEnumerable<string> ShaderFamilyNames => _shaderCache.MadeNames;

        /// <summary>When true, <see cref="RenderSkybox"/> draws the IBL environment cubemap.</summary>
        public static bool ShowSkybox { get; set; } = true;

        /// <summary>
        /// Draws the loaded IBL environment cubemap as the scene background. Call inside an
        /// active pass, BEFORE geometry (it never writes depth, so geometry layers on top).
        /// No-op when no environment is loaded or <see cref="ShowSkybox"/> is false.
        /// Tonemap matches the PBR forward path (ACES Narkowicz, exposure 1) for an LDR target.
        /// </summary>
        public static void RenderSkybox(in Matrix4x4 viewProj, bool offscreen = true, bool hdr = false)
        {
            if (!_initialized || !ShowSkybox) return;
            if (_environment is { IsLoaded: true } env)
                _skyboxPass.Render(in viewProj, env, offscreen, exposure: FallbackExposure,
                                   tonemapType: Tonemapping == TonemapMode.Aces && Fallback ? 2 : Tonemapping == TonemapMode.Neutral && Fallback ? 4 : 0,
                                   hdr: hdr);   // the curve: the tonemap pass's (HDR), or the fallback's, or none
        }

        // ── Environment authoring ─────────────────────────────────────────────────────────

        /// <summary>The settings backing the current environment (copy; safe to mutate).</summary>
        public static EnvironmentSettings CurrentEnvironmentSettings
            => (_envSettings ?? new EnvironmentSettings()).Clone();

        /// <summary>
        /// Applies an <see cref="EnvironmentSettings"/>: rebuilds the IBL environment only when the
        /// source (mode / cubemap folder / per-face overrides) changes; intensity, Y-rotation, and
        /// the skybox toggle update in place so the editor sliders stay live. Cubemap loads are
        /// async — the previous environment stays visible until the new faces are ready.
        /// </summary>
        public static void ApplyEnvironment(EnvironmentSettings settings, bool forceRebuild = false)
        {
            if (!_initialized) return;
            int gen = ++_envGeneration;   // invalidates any in-flight async cubemap load
            bool rebuild = forceRebuild || _environment == null || _envSettings == null || settings.RequiresRebuild(_envSettings);
            _envSettings = settings.Clone();
            ShowSkybox   = settings.ShowSkybox;

            float rotRad = settings.RotationDegrees * (MathF.PI / 180f);

            if (!rebuild && _environment != null)
            {
                _environment.Intensity = settings.Intensity;
                _environment.Rotation  = Matrix4x4.CreateRotationY(rotRad);
                UpdateAmbient();
                return;
            }

            if (settings.Mode == EnvironmentMode.Procedural)
            {
                var env = EnvironmentMap.CreateProcedural("procedural-ibl");
                env.Intensity = settings.Intensity;
                env.Rotation  = Matrix4x4.CreateRotationY(rotRad);
                SwapEnvironment(env);
                _pbrIblLogCount = 0;
                return;
            }

            // Cubemap: bootstrap a procedural env only if nothing is showing yet, then load the
            // faces async and swap on success (a missing/failed set leaves the current env intact).
            if (_environment == null)
            {
                var boot = EnvironmentMap.CreateProcedural("procedural-ibl");
                boot.Intensity = settings.Intensity;
                boot.Rotation  = Matrix4x4.CreateRotationY(rotRad);
                SwapEnvironment(boot);
            }
            float intensity = settings.Intensity;
            IblSkyboxLoader.LoadAsync(settings.CubemapFolder, settings.FaceOverrides, env =>
            {
                if (env == null) return;
                if (gen != _envGeneration) { env.Dispose(); return; } // superseded by a newer ApplyEnvironment
                env.Intensity = intensity;
                env.Rotation  = Matrix4x4.CreateRotationY(rotRad);
                SwapEnvironment(env);
                _pbrIblLogCount = 0;
                Logger.Info("[IBL] environment set to skybox cubemap");
            });
            UpdateAmbient();
        }

        private static void SwapEnvironment(EnvironmentMap env)
        {
            var old = _environment;
            _environment = env;
            old?.Dispose();
            UpdateAmbient();
        }

        private static void UpdateAmbient()
        {
            Array.Clear(_ambientSky);
            var s = _envSettings;
            if (s == null) return;
            float e = s.AmbientEnergy;
            switch (s.Ambient)
            {
                case AmbientSource.Color:
                    _ambientConst     = s.AmbientColor * e;
                    _pbrAmbientParams = new Vector4(0f, _ambientConst.X, _ambientConst.Y, _ambientConst.Z);
                    break;
                case AmbientSource.Disabled:
                    _ambientConst     = Vector3.Zero;
                    _pbrAmbientParams = Vector4.Zero;
                    break;
                default:
                    _pbrAmbientParams = new Vector4(e, 0f, 0f, 0f);
                    if (_environment?.Ambient is { } sky)
                    {
                        _ambientConst = Vector3.Zero;
                        sky.Rotated(_environment.Rotation).Pack(_ambientSky, _environment.Intensity * e * BlinnSkyAmbientScale);
                    }
                    else _ambientConst = new Vector3(0.1f, 0.1f, 0.1f);
                    break;
            }
        }

        /// <summary>The sprites drawn for the last view, and the draw calls they took (a run of sprites of one image is one).</summary>
        public static (int Sprites, int DrawCalls) SpriteStats => (Sprites2D.SpriteRenderSystem.LastSprites, Sprites2D.SpriteRenderSystem.LastDrawCalls);

        /// <summary>
        /// Draws a view of the world into the pass that is open: the meshes, then the sprites (back to front,
        /// tested against the meshes' depth).
        /// </summary>
        public static void SubmitView(
            in Matrix4x4 viewProj,
            PipelineFlags basePipelineFlags = PipelineFlags.OffscreenRt,
            int viewIndex = 0,
            bool allowShadowPassRendering = true,
            CsmCamera? csm = null)
        {
            if (!_initialized) return;
            _hdrPass = (basePipelineFlags & PipelineFlags.Hdr) != 0;
            SubmitMeshes(in viewProj, basePipelineFlags, viewIndex, allowShadowPassRendering, csm);
            // Into an HDR target the sprites are not drawn here: they come after the tone curve (DrawSprites, G8.3 —
            // their batch draws into RGBA8 targets only).
            if (!_hdrPass)
            {
                Sprites2D.SpriteRenderSystem.Draw(ECSWorld.Instance, in viewProj, (basePipelineFlags & PipelineFlags.OffscreenRt) != 0);
                Text3DRenderer.Draw(ECSWorld.Instance, in viewProj, (basePipelineFlags & PipelineFlags.OffscreenRt) != 0);
                if (DrawScriptLines && (basePipelineFlags & PipelineFlags.OffscreenRt) != 0) ScriptLinesRenderer.Draw(in viewProj);
            }
        }

        private static void SubmitMeshes(
            in Matrix4x4 viewProj,
            PipelineFlags basePipelineFlags,
            int viewIndex,
            bool allowShadowPassRendering,
            CsmCamera? csm)
        {
            var world = ECSWorld.Instance;

            // Per-view: deferred transmission (refractive) draws are collected during extraction
            // below and consumed by RenderTransmission after this view's opaque pass ends.
            _transmissionDraws.Clear();

            // Camera position is required for light importance ranking.
            Matrix4x4.Invert(viewProj, out var invVP);
            var cameraPos = EyeOf(in invVP);

            // ── 1. Collect lights and shadow matrices ───────────────────────────────────
            // Re-derives the same CSM cascades RenderShadowMaps computed (cheap, no re-render),
            // so the color pass binds matching cascade VPs + split depths.

            CollectLightsAndShadows(world, in viewProj, allowShadowPassRendering, csm);
            if ((uint)viewIndex < (uint)_viewLighting.Length) _viewLighting[viewIndex] = (ViewIsClustered, ViewLights);

            // ── 1b. Skinned characters (GPU skinning) ────────────────────────────────────
            // Drawn here, before the static-mesh early-returns below, so a scene with ONLY a
            // rigged character still renders. Opaque + depth-tested, so order vs. static is free.
            DrawSkinnedEntities(world, in viewProj, cameraPos, basePipelineFlags);

            // ── 2. Extract draw commands ──────────────────────────────────────────────────

            FrameProfiler.Begin(FrameProfiler.Zone.EcsExtract);
            _drawCount = 0;
            // Gate per-entity TryGetComponent<LodGroup> behind a cheap per-frame archetype check
            // so non-LOD scenes pay nothing for this feature on the hot path.
            bool anyLodGroups = world.HasAnyComponent<LodGroup>();
            // Resolve this view's LOD-history bucket ONCE, with the view-index bounds check
            // here rather than per entity in the loop. A stray viewIndex yields a null bucket,
            // so the entity simply renders without LOD history (LOD 0) instead of faulting.
            System.Collections.Generic.Dictionary<Entity, int>? lodHistory =
                anyLodGroups && (uint)viewIndex < (uint)_prevLodLevel.Length
                    ? _prevLodLevel[viewIndex]
                    : null;
            foreach (var row in world.Query<ActiveFlag, MeshRenderer, Transform>()
                                     .EnumerateWithEntities<ActiveFlag, MeshRenderer, Transform>())
            {
                if (_drawCount >= RenderingConstants.MAX_DRAWS) break;
                if (!row.Item1.Value.Active) continue;
                ref readonly var mr = ref row.Item2.Value;
                if (!mr.Visible) continue;
                ref readonly var tf = ref row.Item3.Value;

                MeshResource? meshRes = _meshReg.GetByPath(mr.MeshPath);
                if (meshRes == null) continue;

                bool disableSubMeshMaterial = string.Equals(
                    mr.MaterialPath,
                    MeshRenderer.NoMaterialSentinel,
                    StringComparison.Ordinal);

                ushort matId;
                if (string.IsNullOrEmpty(mr.MaterialPath) || disableSubMeshMaterial)
                {
                    matId = 0;
                }
                else
                {
                    matId = _matReg.GetIdByKey(mr.MaterialPath);
                    if (matId == 0)
                        matId = _matReg.GetFirstIdByMtlFile(mr.MaterialPath);
                }
                ushort drawFlags = disableSubMeshMaterial ? DrawFlagDisableSubMeshMaterial : (ushort)0;

                Matrix4x4 model    = Transform.GetWorldMatrix(world, tf);
                Aabb worldAabb      = meshRes.LocalBounds.Transform(model);
                float worldRadius   = worldAabb.Extents.Length();
                float dist          = Vector3.Distance(cameraPos, worldAabb.Center);

                // ── Transmission (screen-space refraction) ──────────────────────────────────
                // Glass-type materials are pulled out of the opaque/transparent queue entirely and
                // drawn in RenderTransmission (it samples a copy of the opaque scene). Base mesh only
                // (no LOD/instancing — glass is rare). Skinned/morph transmission is not yet wired.
                if (matId != 0 && _matReg.GetById(matId) is PbrMaterial { IsTransmissive: true } txMat)
                {
                    if (_transmissionDraws.Count < TransmissionDrawCap)
                        _transmissionDraws.Add((model, meshRes, txMat));
                    continue;
                }

                // ── LOD selection ─────────────────────────────────────────────────────────
                Entity entity = row.Entity;
                LodGroup? lodGroup = null;
                int prevLod = 0;
                if (lodHistory != null)
                {
                    lodGroup = world.TryGetComponent<LodGroup>(entity, out var lgVal) ? lgVal : (LodGroup?)null;
                    lodHistory.TryGetValue(entity, out prevLod);
                }
                int lodIndex = LodSelector.Pick(worldRadius, dist, prevLod, lodGroup);
                if (lodIndex == LodSelector.Skip) { _stats.Culled++; continue; }

                // Update per-view, per-entity hysteresis state (only when entity has a LodGroup;
                // lodGroup.HasValue implies lodHistory != null — it was only set inside the guard).
                if (lodHistory != null && lodGroup.HasValue && prevLod != lodIndex)
                {
                    lodHistory[entity] = lodIndex;
                    _stats.LodSwitches++;
                }

                ushort lodMask = (ushort)(drawFlags | (ushort)(lodIndex & 0xF));
                _cmds[_drawCount]    = new DrawCommand(meshRes.Id, matId, lodMask, 0, (uint)entity.GetHashCode(), worldAabb.Center, worldRadius);
                _cpuInst[_drawCount] = new InstanceData(
                    in model,
                    new Vector4(1f, 1f, 1f, mr.ReceivesShadows ? 1f : 0f));
                _drawCount++;
            }

            FrameProfiler.End(FrameProfiler.Zone.EcsExtract);
            if (_drawCount == 0) return;

            // ── 2b. Frustum cull (parallel on non-WASM) ───────────────────────────────────

            var frustum = Frustum.ExtractFromViewProj(in viewProj);
            FrameProfiler.Begin(FrameProfiler.Zone.ParallelCull);
            ParallelCuller.Run(in frustum, _cmds, _drawCount, _visible, out int visibleCount);
            FrameProfiler.End(FrameProfiler.Zone.ParallelCull);
            _stats.TotalRenderable += _drawCount;
            _stats.Culled += _drawCount - visibleCount;
            if (visibleCount == 0) return;

            // ── 3. Sort: opaque first (material/mesh-batched), transparent last (back-to-front) ──
            // Transparent draws must come after every opaque draw — otherwise an opaque object
            // behind a blended one (drawn earlier, depth-write off) re-writes depth+colour over it.
            // Within transparent, far→near (back-to-front) is required for correct alpha blending.

            FrameProfiler.Begin(FrameProfiler.Zone.Sort);
            for (int j = 0; j < visibleCount; j++)
            {
                int idx = _visible[j];
                uint noMatBit = (_cmds[idx].LodMask & DrawFlagDisableSubMeshMaterial) != 0 ? 1u : 0u;
                uint lod      = (uint)(_cmds[idx].LodMask & 0x0F);
                // Opaque batch key (low 32 bits — groups identical mesh+material for instancing):
                //   bits 31-28: lodIndex   (4 bits  — separates LOD variants of the same mesh)
                //   bits 27-16: MaterialId (12 bits — 0-4095 IDs fit; sufficient for editor)
                //   bit  15:    noMatBit
                //   bits 14-0:  MeshId     (15 bits — 0-32767 meshes)
                // Sort-key capacity guard. `if (overflow) Debug.Fail(...)` builds the
                // interpolated message ONLY on actual overflow — Debug.Assert(cond, $"...")
                // would build it eagerly every iteration in Debug builds. Both the Debug.Fail
                // call and the now-empty branch vanish in Release ([Conditional("DEBUG")] +
                // JIT dead-code elimination of the side-effect-free test).
                if ((_cmds[idx].MaterialId & ~0xFFFu) != 0)
                    System.Diagnostics.Debug.Fail($"MaterialId {_cmds[idx].MaterialId} exceeds 12-bit sort-key capacity (max 4095).");
                if ((_cmds[idx].MeshId & ~0x7FFFu) != 0)
                    System.Diagnostics.Debug.Fail($"MeshId {_cmds[idx].MeshId} exceeds 15-bit sort-key capacity (max 32767).");
                uint opaqueKey = (lod << 28)
                               | (((uint)_cmds[idx].MaterialId & 0xFFF) << 16)
                               | (noMatBit << 15)
                               | ((uint)_cmds[idx].MeshId & 0x7FFF);

                // Opaque: bit 63 = 0, low 32 bits = opaqueKey → ordering (and instancing batches)
                // unchanged from before transparency existed. Transparent: bit 63 = 1 (after every
                // opaque draw), then inverted camera distance so FAR sorts first = back-to-front.
                // The blend pipeline (depth-write off) is already chosen per-material in the Draw*
                // helpers — this only fixes the ORDER they're submitted in. Alpha-MASK is NOT
                // transparent (stays opaque, depth-tested, alpha-tested in-shader) per the glTF spec.
                if (IsMaterialTransparent(_matReg.GetById(_cmds[idx].MaterialId)))
                {
                    float dist     = Vector3.Distance(cameraPos, _cmds[idx].BoundsCenter);
                    uint  distBits = BitConverter.SingleToUInt32Bits(dist); // dist>=0 → bit pattern monotonic
                    _sortKeys[idx] = (1UL << 63)
                                   | ((ulong)(~distBits) << 31)   // far → small key → drawn first
                                   | (opaqueKey & 0x7FFFFFFFUL);  // equal-depth tiebreak: keep same-mat batches
                }
                else
                {
                    _sortKeys[idx] = opaqueKey;
                }
                _sortOrder[j] = idx;
            }
            Array.Sort(_sortOrder, 0, visibleCount, _drawSorter);
            FrameProfiler.End(FrameProfiler.Zone.Sort);

            // ── 4. Write instance data in sorted order; ONE sg_append_buffer per view ──────

            FrameProfiler.Begin(FrameProfiler.Zone.InstanceWrite);
            _instanceBuf.ResetStaging();
            int submitCount = visibleCount;
            for (int j = 0; j < visibleCount; j++)
            {
                if (!_instanceBuf.TryAppend(in _cpuInst[_sortOrder[j]]))
                {
#if DEBUG
                    _stats.InstancesDropped += visibleCount - j;
#endif
                    submitCount = j;  // clamp: group-walking loop must not exceed staged range
                    break;
                }
            }
            if (submitCount == 0) { FrameProfiler.End(FrameProfiler.Zone.InstanceWrite); return; }
            int instanceBaseByteOffset = _instanceBuf.Flush();
            _stats.InstancesSubmitted += submitCount;
            FrameProfiler.End(FrameProfiler.Zone.InstanceWrite);

            // ── 5. Camera position from inverse VP ────────────────────────────────────────

            var vsParams = new blinn_phong_vs_params_t
            {
                view_proj  = viewProj,
                camera_pos = new Vector4(cameraPos, 1f),
                dir_shadow_vp = _hasDirectionalShadow ? _directionalShadowViewProj : Matrix4x4.Identity,
            };

            // PBR view-constant uniform blocks. Built lazily on the first PBR group so
            // scenes with no PBR materials never touch them (the light block is ~4 KB).
            bool pbrSharedBuilt = false;
            pbr_pbr_vs_params_t     pbrVs     = default;
            pbr_pbr_light_params_t  pbrLights = default;
            pbr_pbr_camera_params_t pbrCam    = default;
            pbr_pbr_ibl_params_t    pbrIbl    = default;

            // ── 6. Walk sorted groups ─────────────────────────────────────────────────────

            FrameProfiler.Begin(FrameProfiler.Zone.DrawCalls);
            int instanceOffset = 0;
            int i = 0;

            while (i < submitCount)
            {
                int firstIdx = _sortOrder[i];
                ushort curMat  = _cmds[firstIdx].MaterialId;
                ushort curMesh = _cmds[firstIdx].MeshId;
                  bool disableSubMeshMaterial = (_cmds[firstIdx].LodMask & DrawFlagDisableSubMeshMaterial) != 0;
                int  curLod  = _cmds[firstIdx].LodMask & 0x0F;

                int groupSize = 0;
                while (i + groupSize < submitCount
                       && _cmds[_sortOrder[i + groupSize]].MaterialId == curMat
                      && _cmds[_sortOrder[i + groupSize]].MeshId     == curMesh
                      && ((_cmds[_sortOrder[i + groupSize]].LodMask & DrawFlagDisableSubMeshMaterial) != 0) == disableSubMeshMaterial
                      && (_cmds[_sortOrder[i + groupSize]].LodMask & 0x0F) == curLod)
                    groupSize++;

                Material?     mat  = _matReg.GetById(curMat);
                MeshResource? mesh = _meshReg.GetById(curMesh);

                // Pick the LOD mesh: lodIndex 0 = base mesh; lodIndex > 0 = LodSlots[lodIndex-1]
                if (curLod > 0 && mesh?.LodSlots is { Length: > 0 } slots)
                {
                    int slotIdx = curLod - 1;
                    if (slotIdx < slots.Length && slots[slotIdx] != null)
                        mesh = slots[slotIdx];
                    // else fall through: missing LOD slot → keep rendering base mesh
                }

                if (mesh == null || mesh.SubMeshes == null || mesh.SubMeshes.Length == 0)
                {
                    instanceOffset += groupSize;
                    i += groupSize;
                    continue;
                }

                if (mat == null && !HasSubMeshMaterial(mesh, disableSubMeshMaterial)) mat = _defaultMat;

                // ── PBR path ──────────────────────────────────────────────────────────────
                // PBR materials are applied whole-group (no per-sub-mesh .mtl override).
                if (mat is PbrMaterial pbrMat)
                {
                    int pbrInstByteOffset = instanceBaseByteOffset
                                          + instanceOffset * Unsafe.SizeOf<InstanceData>();

                    // Pick the shadow-receiving variant: CSM4 (4 cascades, slices 0-3) when the
                    // camera supplied frustum data, else CSM1 (single slice-0 map), else no shadow.
                    if (_csmCascadeCount == 4)
                    {
                        DrawPbrCsm4Group(pbrMat, mesh, groupSize, pbrInstByteOffset,
                            basePipelineFlags, in viewProj, cameraPos);
                    }
                    else if (_hasDirectionalShadow)
                    {
                        DrawPbrCsm1Group(pbrMat, mesh, groupSize, pbrInstByteOffset,
                            basePipelineFlags, in viewProj, cameraPos);
                    }
                    else
                    {
                        if (!pbrSharedBuilt)
                        {
                            BuildPbrSharedUniforms(in viewProj, cameraPos,
                                out pbrVs, out pbrLights, out pbrCam, out pbrIbl);
                            pbrSharedBuilt = true;
                        }
                        DrawPbrGroup(pbrMat, mesh, groupSize, pbrInstByteOffset, basePipelineFlags,
                            in pbrVs, in pbrLights, in pbrCam, in pbrIbl);
                    }

                    instanceOffset += groupSize;
                    i += groupSize;
                    continue;
                }

                bool groupAlpha = mat is BlinnPhongMaterial bpmG && bpmG.HasAlpha;
                sg_apply_pipeline(_shaderCache.GetPipeline(
                    groupAlpha
                        ? basePipelineFlags | PipelineFlags.AlphaBlend
                        : basePipelineFlags));

                // Apply VS uniforms after pipeline (required by sokol validation).
                sg_apply_uniforms(UB_blinn_phong_vs_params, SG_RANGE(ref vsParams));

                int instByteOffset = instanceOffset * Unsafe.SizeOf<InstanceData>();

                foreach (MeshSubResource sub in mesh.SubMeshes)
                {
                    if (sub.IndexCount == 0 || sub.VertexBuffer.id == 0 || sub.IndexBuffer.id == 0)
                        continue;

                    // Per-sub-mesh material override (from .mtl material name).
                    BlinnPhongMaterial? bpm = ResolveSubMeshMaterial(mat, mesh, sub, disableSubMeshMaterial);
                    bool subAlpha = bpm?.HasAlpha ?? groupAlpha;

                    // If alpha state differs from group, re-apply pipeline then VS uniforms.
                    if (subAlpha != groupAlpha)
                    {
                        sg_apply_pipeline(_shaderCache.GetPipeline(
                            subAlpha
                                ? basePipelineFlags | PipelineFlags.AlphaBlend
                                : basePipelineFlags));
                        sg_apply_uniforms(UB_blinn_phong_vs_params, SG_RANGE(ref vsParams));
                    }

                    // Always apply FS uniforms per sub-mesh: each sub-mesh can have distinct
                    // Kd/Ks/Ns values from the .mtl file, independent of the group-level material.
                    BuildFsParams(bpm ?? mat, cameraPos, out var subFs);
                    LowTierUniforms.ApplyBlinnFs(UB_blinn_phong_fs_params, in subFs, _shaderCache.CurrentLow);

                    sg_view  diffuse  = bpm?.DiffuseMap  ?? _texCache.PlaceholderWhite;
                    sg_view  specular = bpm?.SpecularMap ?? _texCache.PlaceholderWhite;
                    sg_view  normal   = bpm?.NormalMap   ?? _texCache.PlaceholderNormal;
                    sg_view  opacity  = bpm?.OpacityMap  ?? _texCache.PlaceholderWhite;
                    sg_sampler smp    = (bpm?.Sampler.id ?? 0) != 0
                                        ? bpm!.Sampler
                                        : _texCache.DefaultSampler;

                    sg_apply_bindings(new sg_bindings
                    {
                        vertex_buffers        = { [0] = sub.VertexBuffer, [1] = _instanceBuf.Buffer },
                        vertex_buffer_offsets = { [1] = instanceBaseByteOffset + instByteOffset },
                        index_buffer          = sub.IndexBuffer,
                        views = {
                            [VIEW_diffuse_map]  = diffuse,
                            [VIEW_specular_map] = specular,
                            [VIEW_normal_map]   = normal,
                            [VIEW_opacity_map]  = opacity,
                            [VIEW_shadow_atlas] = _shadowAtlas.TextureView,
                            [VIEW_cube_shadow_array] = _cubeShadows.TextureView,
                        },
                        samplers = {
                            [SMP_diffuse_smp]  = smp,
                            [SMP_specular_smp] = smp,
                            [SMP_normal_smp]   = smp,
                            [SMP_opacity_smp]  = smp,
                            [SMP_shadow_atlas_smp] = _shadowSampler,
                            [SMP_cube_shadow_array_smp] = _cubeShadowSampler,
                        },
                    });

                    sg_draw(0u, (uint)sub.IndexCount, (uint)groupSize);
                    _stats.DrawCalls++;
                }

                instanceOffset += groupSize;
                i += groupSize;
            }
            FrameProfiler.End(FrameProfiler.Zone.DrawCalls);
        }

        public static void EndFrame() { FrameProfiler.EndFrame(); }

        /// <summary>
        /// Draws a shadow atlas debug overlay in the bottom-right corner.
        /// Must be called inside an active <c>sg_begin_pass / sg_end_pass</c>.
        /// </summary>
        public static void DrawShadowAtlasDebug(int rtWidth, int rtHeight)
        {
            if (!_initialized || !ShowShadowAtlasDebug) return;
            int size = System.Math.Min(rtWidth, rtHeight) / 4;
            int x    = rtWidth  - size - 8;
            int y    = rtHeight - size - 8;
            _shadowDebugPass.Draw(_shadowAtlas.TextureView,
                ShadowAtlasDebugSlice, x, y, size, rtWidth, rtHeight);
        }

        // ── Helpers ──────────────────────────────────────────────────────────────────────

        /// <summary>
        /// The camera's position from its inverse view-projection: the last row over its w — the middle of the near plane,
        /// a near distance (0.1) from the eye; an orthographic camera's w is 1. The row alone, used before G8.6, is the eye
        /// divided by the near distance for a perspective camera (ten times as far at 0.1): the shading's view vector,
        /// the LOD distances, the transparent order and the light ranking were all taken from there
        /// (examples/GameEditor/docs/CAMERA_POSITION_DESIGN.md).
        /// </summary>
        internal static Vector3 EyeOf(in Matrix4x4 invViewProj)
            => new Vector3(invViewProj.M41, invViewProj.M42, invViewProj.M43) / invViewProj.M44;

        private static void CollectLightsAndShadows(ECSWorld world, in Matrix4x4 cameraViewProj, bool renderShadowPasses, CsmCamera? csm = null, bool forDrawing = true)
        {
            Matrix4x4.Invert(cameraViewProj, out var _invCamVP);
            Vector3 cameraPos = EyeOf(in _invCamVP);   // for ranking the lights by distance
            _lightBuf.Reset();
            _topLightCount = 0;
            // Forward+ for this view: a perspective camera (csm), the project's path, a GPU that draws the full shaders.
            ViewIsClustered = Path == RenderingPath.ForwardPlus && csm.HasValue && ShaderVariantCache.ClusteredAllowed;
            if (ViewIsClustered) _clusterData ??= new ClusterData(ClusterData.MaxLightsFor(sg_query_backend()));
            _topLightCap = Math.Clamp(MaxLights, 1, ViewIsClustered ? _clusterData!.MaxLights : RenderingConstants.MAX_LIGHTS);
            _spotShadowTopCount = 0;
            _pointShadowTopCount = 0;
            _hasDirectionalShadow = false;
            _csmCascadeCount = 0;
            _directionalShadowViewProj = Matrix4x4.Identity;
            for (int si = 0; si < _spotShadowViewProj.Length; si++)
                _spotShadowViewProj[si] = Matrix4x4.Identity;
            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
                _pointShadowViewProj[pi] = Matrix4x4.Identity;

            Light bestDirectionalShadowLight = default;
            float bestDirectionalShadowScore = float.NegativeInfinity;
            bool hasDirectionalShadowLight = false;
            bool anyDirectionalLight = false;

            foreach (var row in world.Query<ActiveFlag, LightComponent, Transform>()
                                     .EnumerateWithEntities<ActiveFlag, LightComponent, Transform>())
            {
                if (!row.Item1.Value.Active) continue;
                ref readonly var lc = ref row.Item2.Value;
                if (!lc.Enabled) continue;
                if (lc.Type == GameEditor.Framework.ECS.Components.LightType.Directional) anyDirectionalLight = true;
                ref readonly var lt = ref row.Item3.Value;

                Matrix4x4 lightWorld = Transform.GetWorldMatrix(world, lt);
                var worldPos = new Vector3(lightWorld.M41, lightWorld.M42, lightWorld.M43);
                var fwd = Vector3.Normalize(new Vector3(lightWorld.M31, lightWorld.M32, lightWorld.M33));

                float importance = MathF.Max(lc.Intensity, 0f);
                if (lc.Type != GameEditor.Framework.ECS.Components.LightType.Directional)
                {
                    float distSq = Vector3.DistanceSquared(cameraPos, worldPos);
                    importance *= 1f / MathF.Max(distSq, 0.01f);
                }

                float innerRad = lc.InnerAngle * (MathF.PI / 180f);
                float outerRad = lc.OuterAngle * (MathF.PI / 180f);

                var l = new Light(
                    (Lighting.LightType)(int)lc.Type,
                    worldPos,
                    fwd,
                    lc.Color,
                    lc.Intensity,
                    lc.Range,
                    innerRad,
                    outerRad
                );
                TryInsertTopLight(in l, importance);

                if (lc.CastsShadows && lc.Type == GameEditor.Framework.ECS.Components.LightType.Directional && importance > bestDirectionalShadowScore)
                {
                    bestDirectionalShadowScore = importance;
                    bestDirectionalShadowLight = l;
                    hasDirectionalShadowLight = true;
                }

                // PunctualShadows off (the quality level): spot and point lights are lit without their shadows (G8.5).
                if (PunctualShadows && lc.CastsShadows && lc.Type == GameEditor.Framework.ECS.Components.LightType.Spot)
                {
                    TryInsertTopSpotShadow(row.Entity, importance);
                }
                else if (PunctualShadows && lc.CastsShadows && lc.Type == GameEditor.Framework.ECS.Components.LightType.Point)
                {
                    TryInsertTopPointShadow(row.Entity, importance);
                }
            }

            if (!anyDirectionalLight && PreviewSunDirection is { } sunDir)
            {
                var sun = new Light(Lighting.LightType.Directional, Vector3.Zero, Vector3.Normalize(sunDir),
                                    Vector3.One, 1f, 0f);
                TryInsertTopLight(in sun, float.MaxValue);
                bestDirectionalShadowLight = sun;
                hasDirectionalShadowLight  = true;
            }

            for (int li = 0; li < _topLightCount; li++)
            {
                if (hasDirectionalShadowLight && IsSameLight(in _topLights[li], in bestDirectionalShadowLight))
                {
                    _topLights[li] = new Light(
                        _topLights[li].Type,
                        _topLights[li].Position,
                        _topLights[li].Direction,
                        _topLights[li].Color,
                        _topLights[li].Intensity,
                        _topLights[li].Range,
                        _topLights[li].InnerAngle,
                        _topLights[li].OuterAngle,
                        0);
                }
            }

            if (hasDirectionalShadowLight && csm.HasValue && EnableCsm4)
            {
                // ── CSM4: fit 4 cascades to the camera frustum, render into atlas slices 0-3 ──
                var cc = csm.Value;
                _csm.Compute(cc.View, cc.Proj, cc.Near, cc.Far,
                    bestDirectionalShadowLight.Direction, _shadowAtlas.SliceSize, CsmComputer.MaxCascades);
                for (int c = 0; c < CsmComputer.MaxCascades; c++) _csmCascadeVP[c] = _csm.CascadeVP[c];
                _csmSplitDepths = new Vector4(_csm.SplitDepths[0], _csm.SplitDepths[1],
                                              _csm.SplitDepths[2], _csm.SplitDepths[3]);
                _csmCameraView             = cc.View;
                _csmCascadeCount           = CsmComputer.MaxCascades;
                _directionalShadowViewProj = _csmCascadeVP[0];   // blinn-phong samples slice 0 = cascade 0
                _hasDirectionalShadow      = true;
                if (renderShadowPasses)
                {
                    _stats.ShadowDrawCalls += _shadowPass.RenderDirectionalCsmCounted(
                        world, _meshReg, _shadowAtlas, 0, _csmCascadeVP.AsSpan(0, CsmComputer.MaxCascades));
                    // Skinned characters cast into the same cascades (depth LOAD, on top of statics).
                    if (world.HasAnyComponent<Animation.SkinnedMeshRenderer>())
                        _stats.ShadowDrawCalls += _shadowPass.RenderSkinnedDirectionalCsm(
                            world, _shadowAtlas, 0, _csmCascadeVP.AsSpan(0, CsmComputer.MaxCascades));
                }
            }
            else if (hasDirectionalShadowLight && TryComputeCasterBounds(world, out var casterMin, out var casterMax))
            {
                // ── CSM1: single caster-fit map (camera-independent) into atlas slice 0 ──
                _directionalShadowViewProj = BuildDirectionalShadowViewProj(in bestDirectionalShadowLight, casterMin, casterMax);
                _csmCascadeCount           = 1;
                _hasDirectionalShadow      = true;
                if (renderShadowPasses)
                {
                    _stats.ShadowDrawCalls += _shadowPass.RenderDirectionalCounted(world, _meshReg, _shadowAtlas, 0, in _directionalShadowViewProj);
                    if (world.HasAnyComponent<Animation.SkinnedMeshRenderer>())
                        _stats.ShadowDrawCalls += _shadowPass.RenderSkinnedDirectionalCsm(
                            world, _shadowAtlas, 0,
                            System.Runtime.InteropServices.MemoryMarshal.CreateReadOnlySpan(ref _directionalShadowViewProj, 1));
                }
            }

            for (int si = 0; si < _spotShadowTopCount; si++)
            {
                Entity sid = _spotShadowTopEntities[si];
                if (!world.TryGetComponent<ActiveFlag>(sid, out var sa) || !sa.Active) continue;
                if (!world.TryGetComponent<LightComponent>(sid, out var slc) || slc.Type != GameEditor.Framework.ECS.Components.LightType.Spot || !slc.CastsShadows) continue;
                if (!world.TryGetComponent<Transform>(sid, out var slt)) continue;

                Matrix4x4 lightWorld = Transform.GetWorldMatrix(world, slt);
                var spotPos = new Vector3(lightWorld.M41, lightWorld.M42, lightWorld.M43);
                var spotFwd = Vector3.Normalize(new Vector3(lightWorld.M31, lightWorld.M32, lightWorld.M33));
                float outerRad = slc.OuterAngle * (MathF.PI / 180f);

                Matrix4x4 spotVp = BuildSpotShadowViewProj(spotPos, spotFwd, slc.Range, outerRad);
                int atlasSlice = ShadowAtlas.DirectionalCascades + si;
                if (renderShadowPasses)
                {
                    _stats.ShadowDrawCalls += _shadowPass.RenderSpotCounted(world, _meshReg, _shadowAtlas, atlasSlice, in spotVp);
                    if (world.HasAnyComponent<Animation.SkinnedMeshRenderer>())
                        _stats.ShadowDrawCalls += _shadowPass.RenderSkinnedSpotCounted(world, _shadowAtlas, atlasSlice, in spotVp);
                }
                _spotShadowViewProj[si] = spotVp;

                for (int li = 0; li < _topLightCount; li++)
                {
                    if (_topLights[li].Type != Lighting.LightType.Spot) continue;
                    if (Vector3.DistanceSquared(_topLights[li].Position, spotPos) > 0.0001f) continue;

                    _topLights[li] = new Light(
                        _topLights[li].Type,
                        _topLights[li].Position,
                        _topLights[li].Direction,
                        _topLights[li].Color,
                        _topLights[li].Intensity,
                        _topLights[li].Range,
                        _topLights[li].InnerAngle,
                        _topLights[li].OuterAngle,
                        atlasSlice);
                    break;
                }
            }

            for (int pi = 0; pi < _pointShadowTopCount; pi++)
            {
                Entity pid = _pointShadowTopEntities[pi];
                if (!world.TryGetComponent<ActiveFlag>(pid, out var pa) || !pa.Active) continue;
                if (!world.TryGetComponent<LightComponent>(pid, out var plc) || plc.Type != GameEditor.Framework.ECS.Components.LightType.Point || !plc.CastsShadows) continue;
                if (!world.TryGetComponent<Transform>(pid, out var plt)) continue;

                Matrix4x4 lightWorld = Transform.GetWorldMatrix(world, plt);
                var pointPos = new Vector3(lightWorld.M41, lightWorld.M42, lightWorld.M43);

                bool hasSkinnedCasters = renderShadowPasses && world.HasAnyComponent<Animation.SkinnedMeshRenderer>();
                for (int face = 0; face < CubeShadowArray.FacesPerLight; face++)
                {
                    Matrix4x4 pointFaceVp = BuildPointShadowFaceViewProj(pointPos, face, plc.Range);
                    if (renderShadowPasses)
                    {
                        _stats.ShadowDrawCalls += _shadowPass.RenderPointFaceCounted(world, _meshReg, _cubeShadows, pi, face, in pointFaceVp);
                        if (hasSkinnedCasters)
                            _stats.ShadowDrawCalls += _shadowPass.RenderSkinnedPointFaceCounted(world, _cubeShadows, pi, face, in pointFaceVp);
                    }
                    _pointShadowViewProj[pi * CubeShadowArray.FacesPerLight + face] = pointFaceVp;
                }

                for (int li = 0; li < _topLightCount; li++)
                {
                    if (_topLights[li].Type != Lighting.LightType.Point) continue;
                    if (Vector3.DistanceSquared(_topLights[li].Position, pointPos) > 0.0001f) continue;

                    _topLights[li] = new Light(
                        _topLights[li].Type,
                        _topLights[li].Position,
                        _topLights[li].Direction,
                        _topLights[li].Color,
                        _topLights[li].Intensity,
                        _topLights[li].Range,
                        _topLights[li].InnerAngle,
                        _topLights[li].OuterAngle,
                        pi);
                    break;
                }
            }

            _lightBuf.Reset();
            for (int li = 0; li < _topLightCount; li++)
            {
                _lightBuf.Add(in _topLights[li]);
            }

            // Forward+: every selected light (in the order the shader reads them) into the view's cluster grid — when a
            // view is drawn next (not for the shadow maps alone: a texture is updated once a frame).
            if (ViewIsClustered && forDrawing)
            {
                var cc = csm!.Value;
                for (int li = 0; li < _topLightCount; li++) _clusterLights[li] = new GpuLight(in _topLights[li]);
                var span = new ReadOnlySpan<GpuLight>(_clusterLights, 0, _topLightCount);
                if (_clusterData!.Builder.Build(cc.View, cc.Proj, cc.Near, cc.Far, span))
                {
                    _clusterView = _clusterData.Upload(span, _animationFrame);
                    _clusterParams = new PbrClustered.pbr_clustered_pbr_cluster_params_t
                    {
                        cluster_view_proj = _clusterData.Builder.ViewProj,
                        cluster_params    = _clusterData.Params,
                    };
                }
                else ViewIsClustered = false;
            }
            ShaderVariantCache.UseClustered = ViewIsClustered;
            ViewLights = ViewIsClustered ? _topLightCount : _lightBuf.Count;
        }

        private static readonly GpuLight[] _clusterLights = new GpuLight[MaxSelectableLights];
        /// <summary>The lights the view drawn last is lit by (Forward: at most 32; Forward+: its limit).</summary>
        public static int ViewLights { get; private set; }
        private static readonly (bool Clustered, int Lights)[] _viewLighting = new (bool, int)[RenderingConstants.MAX_VIEWS];
        /// <summary>How view <paramref name="viewIndex"/> was lit when last drawn: Forward+ or Forward, and by how many lights.</summary>
        public static (bool Clustered, int Lights) LightingOf(int viewIndex)
            => (uint)viewIndex < (uint)_viewLighting.Length ? _viewLighting[viewIndex] : default;

        private static void BuildFsParams(Material? mat, Vector3 cameraPos,
                                          out blinn_phong_fs_params_t fs)
        {
            fs = new blinn_phong_fs_params_t();

            if (mat is BlinnPhongMaterial bpm)
            {
                fs.material_kd_alpha = new Vector4(bpm.DiffuseColor,  bpm.Opacity);
                fs.material_ks_shin  = new Vector4(bpm.SpecularColor, bpm.Shininess);
            }
            else
            {
                fs.material_kd_alpha = Vector4.One;
                fs.material_ks_shin  = new Vector4(0f, 0f, 0f, 1f);
            }

            fs.ambient_num = new Vector4(_ambientConst, _lightBuf.Count);
            for (int k = 0; k < _ambientSky.Length; k++) fs.ambient_sky[k] = _ambientSky[k];
            fs.cam_pos_pad = new Vector4(cameraPos, (float)ShadowQuality);

            int n      = _lightBuf.Count;
            var lights = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                fs.lights_data[b + 0] = lights[l].PositionType;
                fs.lights_data[b + 1] = lights[l].DirectionRange;
                fs.lights_data[b + 2] = lights[l].ColorIntensity;
                fs.lights_data[b + 3] = lights[l].SpotShadow;
            }

            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
                int b = si * 4;
                var m = _spotShadowViewProj[si];
                fs.spot_shadow_vp[b + 0] = new Vector4(m.M11, m.M12, m.M13, m.M14);
                fs.spot_shadow_vp[b + 1] = new Vector4(m.M21, m.M22, m.M23, m.M24);
                fs.spot_shadow_vp[b + 2] = new Vector4(m.M31, m.M32, m.M33, m.M34);
                fs.spot_shadow_vp[b + 3] = new Vector4(m.M41, m.M42, m.M43, m.M44);
            }

            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
            {
                int b = pi * 4;
                var m = _pointShadowViewProj[pi];
                fs.point_shadow_vp[b + 0] = new Vector4(m.M11, m.M12, m.M13, m.M14);
                fs.point_shadow_vp[b + 1] = new Vector4(m.M21, m.M22, m.M23, m.M24);
                fs.point_shadow_vp[b + 2] = new Vector4(m.M31, m.M32, m.M33, m.M34);
                fs.point_shadow_vp[b + 3] = new Vector4(m.M41, m.M42, m.M43, m.M44);
            }
        }

        // ── PBR forward path ───────────────────────────────────────────────────────────

        /// <summary>
        /// Builds the four view-constant PBR uniform blocks (vertex params, packed light block,
        /// camera, IBL). Called once per <see cref="SubmitView"/> on the first PBR group.
        /// The light block reuses the same packed GpuLight[32] format as <see cref="BuildFsParams"/>.
        /// </summary>
        private static void BuildPbrSharedUniforms(
            in Matrix4x4 viewProj, Vector3 cameraPos,
            out pbr_pbr_vs_params_t vs,
            out pbr_pbr_light_params_t lights,
            out pbr_pbr_camera_params_t cam,
            out pbr_pbr_ibl_params_t ibl)
        {
            vs = new pbr_pbr_vs_params_t
            {
                view_proj            = viewProj,
                eye_pos              = cameraPos,
                use_uniform_skinning = 1,   // unused by the base variant; reserved for skinning
            };

            lights = new pbr_pbr_light_params_t();
            int n = _lightBuf.Count;
            var span = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                lights.lights_data[b + 0] = span[l].PositionType;
                lights.lights_data[b + 1] = span[l].DirectionRange;
                lights.lights_data[b + 2] = span[l].ColorIntensity;
                lights.lights_data[b + 3] = span[l].SpotShadow;
            }
            // ambient_num.w = light count; ambient colour comes from
            // pbr_rendering_flags.ambient_strength. (Point shadows still pending.)
            // Spot-light shadow VPs (atlas slices 4-11) so PBR surfaces receive spot shadows.
            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
                int sb = si * 4;
                var sm = _spotShadowViewProj[si];
                lights.spot_shadow_vp[sb + 0] = new Vector4(sm.M11, sm.M12, sm.M13, sm.M14);
                lights.spot_shadow_vp[sb + 1] = new Vector4(sm.M21, sm.M22, sm.M23, sm.M24);
                lights.spot_shadow_vp[sb + 2] = new Vector4(sm.M31, sm.M32, sm.M33, sm.M34);
                lights.spot_shadow_vp[sb + 3] = new Vector4(sm.M41, sm.M42, sm.M43, sm.M44);
            }
            // Point-light shadow VPs (cube faces; slice = slot*6 + face) for PBR point shadows.
            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
            {
                int pb = pi * 4;
                var pm = _pointShadowViewProj[pi];
                lights.point_shadow_vp[pb + 0] = new Vector4(pm.M11, pm.M12, pm.M13, pm.M14);
                lights.point_shadow_vp[pb + 1] = new Vector4(pm.M21, pm.M22, pm.M23, pm.M24);
                lights.point_shadow_vp[pb + 2] = new Vector4(pm.M31, pm.M32, pm.M33, pm.M34);
                lights.point_shadow_vp[pb + 3] = new Vector4(pm.M41, pm.M42, pm.M43, pm.M44);
            }
            lights.ambient_num = new Vector4(0f, 0f, 0f, n);

            cam = new pbr_pbr_camera_params_t { u_Camera = cameraPos };

            // IBL view-constants. When an environment is loaded these feed the GGX-mip
            // LOD math (u_MipCount) and irradiance/specular scaling (u_EnvIntensity);
            // u_View/Projection/Model are only consumed by the TRANSMISSION path (unused
            // in the base variant) so they stay identity here.
            bool iblActive = _environment is { IsLoaded: true };
            ibl = new pbr_pbr_ibl_params_t
            {
                u_EnvIntensity      = iblActive ? _environment!.Intensity : 1f,
                u_AmbientParams     = _pbrAmbientParams,
                u_EnvBlurNormalized = 0f,
                u_MipCount          = iblActive ? _environment!.MipCount : 1,
                u_EnvRotation       = iblActive ? _environment!.Rotation : Matrix4x4.Identity,
                u_ViewMatrix        = Matrix4x4.Identity,
                u_ProjectionMatrix  = Matrix4x4.Identity,
                u_ModelMatrix       = Matrix4x4.Identity,
            };
        }

        /// <summary>
        /// Draws one instanced group of a single <see cref="PbrMaterial"/> through the base
        /// PBR variant. Unset texture slots fall back to placeholders; the IBL env slots bind
        /// the placeholder cube (never sampled while use_ibl=0).
        /// </summary>
        private static void DrawPbrGroup(
            PbrMaterial mat, MeshResource mesh, int groupSize, int instanceByteOffset,
            PipelineFlags basePipelineFlags,
            in pbr_pbr_vs_params_t vs,
            in pbr_pbr_light_params_t lights,
            in pbr_pbr_camera_params_t cam,
            in pbr_pbr_ibl_params_t ibl)
        {
            bool blend = mat.AlphaMode == 2;
            PipelineFlags pf = basePipelineFlags;
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            if (blend)           pf |= PipelineFlags.AlphaBlend;
            sg_apply_pipeline(_shaderCache.GetPbrPipeline(pf));

            var matParams = new pbr_pbr_material_params_t
            {
                base_color_factor          = mat.BaseColorFactor,
                emissive_factor            = mat.EmissiveFactor,
                metallic_factor            = mat.MetallicFactor,
                roughness_factor           = mat.RoughnessFactor,
                has_base_color_tex         = mat.BaseColorMap.id         != 0 ? 1f : 0f,
                has_metallic_roughness_tex = mat.MetallicRoughnessMap.id != 0 ? 1f : 0f,
                has_normal_tex             = mat.NormalMap.id            != 0 ? 1f : 0f,
                has_occlusion_tex          = mat.OcclusionMap.id         != 0 ? 1f : 0f,
                has_emissive_tex           = mat.EmissiveMap.id          != 0 ? 1f : 0f,
                alpha_cutoff               = mat.AlphaCutoff,
                emissive_strength          = mat.EmissiveStrength,
                occlusion_strength         = mat.OcclusionStrength,
                ior                        = 1.5f,
                normal_map_scale           = mat.NormalMapScale,
                // KHR_texture_transform (offset/rotation/scale) + per-texture coordinate set —
                // filled from the material (was hardcoded identity, which broke tiled normal maps).
                base_color_texcoord             = mat.BaseColorTexcoord,
                base_color_tex_offset           = mat.BaseColorTexOffset,
                base_color_tex_rotation         = mat.BaseColorTexRotation,
                base_color_tex_scale            = mat.BaseColorTexScale,
                metallic_roughness_texcoord     = mat.MetallicRoughnessTexcoord,
                metallic_roughness_tex_offset   = mat.MetallicRoughnessTexOffset,
                metallic_roughness_tex_rotation = mat.MetallicRoughnessTexRotation,
                metallic_roughness_tex_scale    = mat.MetallicRoughnessTexScale,
                normal_texcoord                 = mat.NormalTexcoord,
                normal_tex_offset               = mat.NormalTexOffset,
                normal_tex_rotation             = mat.NormalTexRotation,
                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                debug_view_enabled           = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode              = PbrDebugViewMode,
                shadow_ambient_weight        = ShadowAmbientWeight,
            };

            bool iblActive = _environment is { IsLoaded: true };
            var flags = new pbr_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,      // LDR RGBA8 target → tonemap + sRGB in-shader
                ambient_strength    = 0.4f,   // dielectric diffuse ambient (pbr.glsl:489) + IBL-off fallback
            };

            sg_apply_uniforms(UB_pbr_pbr_vs_params,       SG_RANGE(ref Unsafe.AsRef(in vs)));
            sg_apply_uniforms(UB_pbr_pbr_material_params, SG_RANGE(ref matParams));
            LowTierUniforms.ApplyPbrLights(UB_pbr_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(UB_pbr_pbr_ibl_params,      SG_RANGE(ref Unsafe.AsRef(in ibl)));
            sg_apply_uniforms(UB_pbr_pbr_camera_params,   SG_RANGE(ref Unsafe.AsRef(in cam)));
            sg_apply_uniforms(UB_pbr_pbr_rendering_flags, SG_RANGE(ref flags));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            // IBL env slots: real prefiltered cubes + BRDF LUT when an environment is
            // loaded, else placeholders (never sampled because use_ibl == 0).
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            // One-shot IBL diagnostics (first few PBR groups only — avoids per-frame spam).
            if (_pbrIblLogCount < 6)
            {
                _pbrIblLogCount++;
                Logger.Info(
                    $"[IBL] PBR draw #{_pbrIblLogCount}: use_ibl={flags.use_ibl} envLoaded={iblActive} " +
                    $"metallic={mat.MetallicFactor:0.##} roughness={mat.RoughnessFactor:0.##} " +
                    $"mrTex={(mat.MetallicRoughnessMap.id != 0 ? 1 : 0)} " +
                    $"baseColor=({mat.BaseColorFactor.X:0.##},{mat.BaseColorFactor.Y:0.##},{mat.BaseColorFactor.Z:0.##}) " +
                    $"views[ggx={ggxEnv.id} lambert={lambEnv.id} lut={lut.id}] mipCount={(iblActive ? _environment!.MipCount : 0)}");
            }

            foreach (MeshSubResource sub in mesh.SubMeshes)
            {
                if (sub.IndexCount == 0 || sub.VertexBuffer.id == 0 || sub.IndexBuffer.id == 0)
                    continue;

                sg_apply_bindings(ClusterBind(new sg_bindings
                {
                    vertex_buffers        = { [0] = sub.VertexBuffer, [1] = _instanceBuf.Buffer },
                    vertex_buffer_offsets = { [1] = instanceByteOffset },
                    index_buffer          = sub.IndexBuffer,
                    views = {
                        [VIEW_pbr_u_BaseColorTexture]         = baseColor,
                        [VIEW_pbr_u_MetallicRoughnessTexture] = metalRgh,
                        [VIEW_pbr_u_NormalTexture]            = normalMap,
                        [VIEW_pbr_u_OcclusionTexture]         = occlusion,
                        [VIEW_pbr_u_EmissiveTexture]          = emissive,
                        [VIEW_pbr_u_GGXEnvTexture]            = ggxEnv,
                        [VIEW_pbr_u_LambertianEnvTexture]     = lambEnv,
                        [VIEW_pbr_u_GGXLUTTexture]            = lut,
                        [VIEW_pbr_shadow_atlas]              = _shadowAtlas.TextureView,
                        [VIEW_pbr_cube_shadow_array]         = _cubeShadows.TextureView,
                    },
                    samplers = {
                        [SMP_pbr_u_BaseColorSampler]         = matSmp,
                        [SMP_pbr_u_MetallicRoughnessSampler] = matSmp,
                        [SMP_pbr_u_NormalSampler]            = matSmp,
                        [SMP_pbr_u_OcclusionSampler]         = matSmp,
                        [SMP_pbr_u_EmissiveSampler]          = matSmp,
                        [SMP_pbr_u_GGXEnvSampler_Raw]        = cubeSmp,
                        [SMP_pbr_u_LambertianEnvSampler_Raw] = cubeSmp,
                        [SMP_pbr_u_GGXLUTSampler_Raw]        = lutSmp,
                        [SMP_pbr_shadow_atlas_smp]           = _shadowSampler,
                        [SMP_pbr_cube_shadow_array_smp]      = _cubeShadowSampler,
                    },
                }));

                sg_draw(0u, (uint)sub.IndexCount, (uint)groupSize);
                _stats.DrawCalls++;
            }
        }

        // ── Transmission (KHR_materials_transmission) — screen-space refraction ─────────────
        // Glass-type surfaces refract the background. Because a shader cannot sample the colour
        // attachment it is drawing into, RenderTransmission runs AFTER the host's opaque pass has
        // ended: it (1) blits the opaque scene into a sampleable screen-copy texture, then
        // (2) re-opens the same target (LOAD colour + depth) and draws the deferred refractive
        // surfaces, which sample the copy along the refracted ray (pbr.glsl getTransmissionIBL).
        // Editor/offscreen only; standalone (swapchain) transmission is deferred.

        private static void EnsureScreenCopy(int w, int h, sg_pixel_format format)
        {
            if (_screenCopyImg.id != 0 && _screenCopyW == w && _screenCopyH == h && _screenCopyFormat == format) return;
            DestroyScreenCopy();
            _screenCopyW = w; _screenCopyH = h; _screenCopyFormat = format;
            _screenCopyImg = sg_make_image(new sg_image_desc
            {
                width = w, height = h,
                pixel_format = format,   // the scene's: RGBA8, or an HDR scene's float format (G8.3)
                // Pinned to 1 (see OffscreenTarget): a render-target image otherwise inherits the
                // swapchain sample count, mismatching the single-sampled screen-copy blit pipeline.
                sample_count = 1,
                usage = { color_attachment = true },
                label = "transmission-screen-copy"
            });
            _screenCopyAttView = sg_make_view(new sg_view_desc
            {
                color_attachment = new sg_image_view_desc { image = _screenCopyImg },
                label = "transmission-screen-copy-att"
            });
            _screenCopyTexView = sg_make_view(new sg_view_desc
            {
                texture = new sg_texture_view_desc { image = _screenCopyImg },
                label = "transmission-screen-copy-tex"
            });
        }

        private static void DestroyScreenCopy()
        {
            if (_screenCopyTexView.id != 0) { sg_destroy_view(_screenCopyTexView); _screenCopyTexView = default; }
            if (_screenCopyAttView.id != 0) { sg_destroy_view(_screenCopyAttView); _screenCopyAttView = default; }
            if (_screenCopyImg.id     != 0) { sg_destroy_image(_screenCopyImg);    _screenCopyImg     = default; }
            _screenCopyW = _screenCopyH = 0;
        }

        /// <summary>
        /// Draws the refractive (KHR_materials_transmission) surfaces deferred by the most recent
        /// <see cref="SubmitView"/> for <paramref name="target"/>. Must be called AFTER that view's
        /// opaque <c>sg_end_pass()</c> and OUTSIDE any active pass (it opens its own passes).
        /// No-op when the view had no transmissive materials.
        /// </summary>
        public static void RenderTransmission(OffscreenTarget target, in Matrix4x4 viewProj)
        {
            if (!_initialized || _transmissionDraws.Count == 0 || !target.IsValid) return;

            int w = target.Width, h = target.Height;
            _hdrPass = target.IsHdr;
            EnsureScreenCopy(w, h, target.ColorFormat);

            // One model matrix (1 instance) per transmission draw → the dedicated instance buffer.
            _transmissionInstanceBuf.ResetStaging();
            int staged = 0;
            for (int k = 0; k < _transmissionDraws.Count; k++)
            {
                var model = _transmissionDraws[k].model;
                if (!_transmissionInstanceBuf.TryAppend(new InstanceData(in model, new Vector4(1f, 1f, 1f, 0f))))
                    break;
                staged++;
            }
            if (staged == 0) return;
            int baseOff = _transmissionInstanceBuf.Flush();

            // 1) Snapshot the opaque scene into the sampleable screen-copy (its own pass).
            var copyPass = new sg_pass
            {
                attachments = { colors = { [0] = _screenCopyAttView } },
                action = { colors = { [0] = new sg_color_attachment_action
                {
                    load_action  = sg_load_action.SG_LOADACTION_DONTCARE,
                    store_action = sg_store_action.SG_STOREACTION_STORE
                } } },
                label = "transmission-screen-copy-pass"
            };
            sg_begin_pass(copyPass);
            _screenCopyPass.Render(target.TexView, target.ColorFormat);
            sg_end_pass();

            // 2) Transmission pass: re-open the scene target preserving opaque colour + depth.
            Matrix4x4.Invert(viewProj, out var invVP);
            var cameraPos = EyeOf(in invVP);
            BuildPbrSharedUniforms(in viewProj, cameraPos, out var vs, out var lights, out var cam, out _);

            var txPass = new sg_pass
            {
                attachments = { colors = { [0] = target.ColorAttView }, depth_stencil = target.DepthAttView },
                action =
                {
                    colors = { [0] = new sg_color_attachment_action
                    {
                        load_action  = sg_load_action.SG_LOADACTION_LOAD,
                        store_action = sg_store_action.SG_STOREACTION_STORE
                    } },
                    depth = new sg_depth_attachment_action
                    {
                        load_action  = sg_load_action.SG_LOADACTION_LOAD,
                        store_action = sg_store_action.SG_STOREACTION_DONTCARE
                    }
                },
                label = "transmission-pass"
            };
            sg_begin_pass(txPass);
            int stride = Unsafe.SizeOf<InstanceData>();
            for (int k = 0; k < staged; k++)
            {
                var (model, mesh, mat) = _transmissionDraws[k];
                DrawPbrTransmissionGroup(mat, mesh, baseOff + k * stride, in model, in viewProj,
                    cameraPos, w, h, in vs, in lights, in cam);
            }
            sg_end_pass();
        }

        /// <summary>
        /// Draws one refractive surface through the <c>pbr_transmission</c> variant. Reuses the
        /// view-constant VS/light/camera blocks built for the base PBR path (identical layouts —
        /// the transmission variant shares the same uniform-block source with no CSM/skinning),
        /// and binds the captured screen copy as the transmission framebuffer (binding 10).
        /// </summary>
        private static void DrawPbrTransmissionGroup(
            PbrMaterial mat, MeshResource mesh, int instanceByteOffset,
            in Matrix4x4 model, in Matrix4x4 viewProj, Vector3 cameraPos, int fbW, int fbH,
            in pbr_pbr_vs_params_t vs,
            in pbr_pbr_light_params_t lights,
            in pbr_pbr_camera_params_t cam)
        {
            // Editor renders to an offscreen RT; standalone (swapchain) transmission is deferred.
            PipelineFlags pf = PipelineFlags.OffscreenRt | (_hdrPass ? PipelineFlags.Hdr : 0);
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            sg_apply_pipeline(_shaderCache.GetPbrTransmissionPipeline(pf));

            bool iblActive = _environment is { IsLoaded: true };

            var matParams = new PbrTx.pbr_transmission_pbr_material_params_t
            {
                base_color_factor          = mat.BaseColorFactor,
                emissive_factor            = mat.EmissiveFactor,
                metallic_factor            = mat.MetallicFactor,
                roughness_factor           = mat.RoughnessFactor,
                has_base_color_tex         = mat.BaseColorMap.id         != 0 ? 1f : 0f,
                has_metallic_roughness_tex = mat.MetallicRoughnessMap.id != 0 ? 1f : 0f,
                has_normal_tex             = mat.NormalMap.id            != 0 ? 1f : 0f,
                has_occlusion_tex          = mat.OcclusionMap.id         != 0 ? 1f : 0f,
                has_emissive_tex           = mat.EmissiveMap.id          != 0 ? 1f : 0f,
                alpha_cutoff               = mat.AlphaCutoff,
                emissive_strength          = mat.EmissiveStrength,
                occlusion_strength         = mat.OcclusionStrength,
                normal_map_scale           = mat.NormalMapScale,
                // KHR_texture_transform (offset/rotation/scale) + per-texture coordinate set —
                // filled from the material (was hardcoded identity, which broke tiled normal maps).
                base_color_texcoord             = mat.BaseColorTexcoord,
                base_color_tex_offset           = mat.BaseColorTexOffset,
                base_color_tex_rotation         = mat.BaseColorTexRotation,
                base_color_tex_scale            = mat.BaseColorTexScale,
                metallic_roughness_texcoord     = mat.MetallicRoughnessTexcoord,
                metallic_roughness_tex_offset   = mat.MetallicRoughnessTexOffset,
                metallic_roughness_tex_rotation = mat.MetallicRoughnessTexRotation,
                metallic_roughness_tex_scale    = mat.MetallicRoughnessTexScale,
                normal_texcoord                 = mat.NormalTexcoord,
                normal_tex_offset               = mat.NormalTexOffset,
                normal_tex_rotation             = mat.NormalTexRotation,
                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                thickness_tex_scale          = Vector2.One,
                // KHR transmission / volume / ior
                transmission_factor   = mat.TransmissionFactor,
                has_transmission_tex  = mat.TransmissionMap.id != 0 ? 1f : 0f,
                transmission_texcoord = mat.TransmissionTexcoord,
                ior                   = mat.Ior,
                attenuation_color     = mat.AttenuationColor,
                attenuation_distance  = mat.AttenuationDistance,
                thickness_factor      = mat.ThicknessFactor,
                has_thickness_tex     = 0f,   // factor-only; thickness-texture path not wired
                thickness_tex_index   = 0f,
                debug_view_enabled    = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode       = PbrDebugViewMode,
                shadow_ambient_weight = ShadowAmbientWeight,
            };

            var ibl = new PbrTx.pbr_transmission_pbr_ibl_params_t
            {
                u_EnvIntensity      = iblActive ? _environment!.Intensity : 1f,
                u_AmbientParams     = _pbrAmbientParams,
                u_EnvBlurNormalized = 0f,
                u_MipCount          = iblActive ? _environment!.MipCount : 1,
                u_EnvRotation       = iblActive ? _environment!.Rotation : Matrix4x4.Identity,
                // getTransmissionIBL uses only the product (Proj*View) to reproject the ray exit
                // point to NDC, so folding the full viewProj into u_ViewMatrix with identity proj
                // is correct and avoids splitting view/proj at the call site.
                u_ViewMatrix        = viewProj,
                u_ProjectionMatrix  = Matrix4x4.Identity,
                u_ModelMatrix       = model,
            };
            ibl.u_TransmissionFramebufferSize[0] = fbW;
            ibl.u_TransmissionFramebufferSize[1] = fbH;

            var flags = new PbrTx.pbr_transmission_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,
                ambient_strength    = 0.4f,
            };

            sg_apply_uniforms(PbrTx.UB_pbr_transmission_pbr_vs_params,       SG_RANGE(ref Unsafe.AsRef(in vs)));
            sg_apply_uniforms(PbrTx.UB_pbr_transmission_pbr_material_params, SG_RANGE(ref matParams));
            // The CLUSTERED transmission shader has no light block: its lights are in the cluster texture, and glass samples
            // no shadows (the block's other contents), so the compiler drops it.
            if (!_shaderCache.CurrentClustered)
                LowTierUniforms.ApplyPbrLights(PbrTx.UB_pbr_transmission_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrTx.UB_pbr_transmission_pbr_ibl_params,      SG_RANGE(ref ibl));
            sg_apply_uniforms(PbrTx.UB_pbr_transmission_pbr_camera_params,   SG_RANGE(ref Unsafe.AsRef(in cam)));
            sg_apply_uniforms(PbrTx.UB_pbr_transmission_pbr_rendering_flags, SG_RANGE(ref flags));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_view transTex  = mat.TransmissionMap.id != 0 ? mat.TransmissionMap : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            foreach (MeshSubResource sub in mesh.SubMeshes)
            {
                if (sub.IndexCount == 0 || sub.VertexBuffer.id == 0 || sub.IndexBuffer.id == 0)
                    continue;

                sg_apply_bindings(ClusterBind(new sg_bindings
                {
                    vertex_buffers        = { [0] = sub.VertexBuffer, [1] = _transmissionInstanceBuf.Buffer },
                    vertex_buffer_offsets = { [1] = instanceByteOffset },
                    index_buffer          = sub.IndexBuffer,
                    views = {
                        [PbrTx.VIEW_pbr_transmission_u_BaseColorTexture]               = baseColor,
                        [PbrTx.VIEW_pbr_transmission_u_MetallicRoughnessTexture]       = metalRgh,
                        [PbrTx.VIEW_pbr_transmission_u_NormalTexture]                  = normalMap,
                        [PbrTx.VIEW_pbr_transmission_u_OcclusionTexture]               = occlusion,
                        [PbrTx.VIEW_pbr_transmission_u_EmissiveTexture]                = emissive,
                        [PbrTx.VIEW_pbr_transmission_u_GGXEnvTexture]                  = ggxEnv,
                        [PbrTx.VIEW_pbr_transmission_u_LambertianEnvTexture]           = lambEnv,
                        [PbrTx.VIEW_pbr_transmission_u_GGXLUTTexture]                  = lut,
                        [PbrTx.VIEW_pbr_transmission_u_TransmissionTexture]            = transTex,
                        [PbrTx.VIEW_pbr_transmission_u_TransmissionFramebufferTexture] = _screenCopyTexView,
                    },
                    samplers = {
                        [PbrTx.SMP_pbr_transmission_u_BaseColorSampler]                   = matSmp,
                        [PbrTx.SMP_pbr_transmission_u_MetallicRoughnessSampler]           = matSmp,
                        [PbrTx.SMP_pbr_transmission_u_NormalSampler]                      = matSmp,
                        [PbrTx.SMP_pbr_transmission_u_OcclusionSampler]                   = matSmp,
                        [PbrTx.SMP_pbr_transmission_u_EmissiveSampler]                    = matSmp,
                        [PbrTx.SMP_pbr_transmission_u_GGXEnvSampler_Raw]                  = cubeSmp,
                        [PbrTx.SMP_pbr_transmission_u_LambertianEnvSampler_Raw]           = cubeSmp,
                        [PbrTx.SMP_pbr_transmission_u_GGXLUTSampler_Raw]                  = lutSmp,
                        [PbrTx.SMP_pbr_transmission_u_TransmissionSampler_Raw]            = matSmp,
                        [PbrTx.SMP_pbr_transmission_u_TransmissionFramebufferSampler_Raw] = _screenSampler,
                    },
                }));

                sg_draw(0u, (uint)sub.IndexCount, 1u);
                _stats.DrawCalls++;
            }
        }

        // Rigid/node animation (e.g. ChronographWatch hands): samples each NodeAnimationPlayer's clip
        // and writes the result into the owning entity's Transform. Runs once per CPU frame at
        // BeginFrame, before any SubmitView reads the Transform. Independent of the skinned path.
        private static void UpdateNodeAnimations()
        {
            var world = ECSWorld.Instance;
            if (!world.HasAnyComponent<Animation.NodeAnimationPlayer>()) return;
            float dt = (float)Sokol.SApp.sapp_frame_duration();
            foreach (var row in world.Query<ActiveFlag, Animation.NodeAnimationPlayer, Transform>()
                                     .EnumerateWithEntities<ActiveFlag, Animation.NodeAnimationPlayer, Transform>())
            {
                if (!row.Item1.Value.Active) continue;
                Entity e = row.Entity;
                ref var player = ref world.GetComponent<Animation.NodeAnimationPlayer>(e);
                var clip = player.Clip;
                if (!player.Playing || clip == null || !clip.HasAnyChannel) continue;

                player.Time += dt;
                if (clip.Duration > 0f)
                {
                    if (player.Loop) { player.Time %= clip.Duration; if (player.Time < 0f) player.Time += clip.Duration; }
                    else if (player.Time > clip.Duration) player.Time = clip.Duration;
                }

                clip.Sample(player.Time, out var t, out var r, out var s);
                ref var tf = ref world.GetComponent<Transform>(e);
                tf.Position = t;
                tf.Rotation = r;
                tf.Scale    = s;
            }
        }

        /// <summary>
        /// (Re)attaches <see cref="Animation.NodeAnimationPlayer"/> to scene entities whose source glTF
        /// has registered node-TRS clips (matched by MeshRenderer→glTF path + the entity's NameTag name).
        /// Idempotent. Runs on scene load + after each glTF preload so rigid/node animation (e.g. the
        /// ChronographWatch hands) survives a cold scene reload without being serialized — mirroring how
        /// skinned entities re-resolve from SkinnedCharacterRegistry.
        /// </summary>
        public static void AttachSceneNodeAnimations()
        {
            if (!_initialized) return;
            var world = ECSWorld.Instance;
            // Match by entity NAME (= glTF node name; round-tripped via NameTag). NOT by MeshRenderer:
            // a multi-primitive animated node (e.g. the watch's "Hand Seconds") has its mesh on CHILD
            // entities, so the animated node entity itself carries only a Transform. Animating that
            // parent Transform rotates the mesh children through the hierarchy.
            foreach (Entity e in world.Entities)
            {
                if (world.TryGetComponent<Animation.NodeAnimationPlayer>(e, out _)) continue;
                if (!world.TryGetComponent<NameTag>(e, out var nt)) continue;
                var clip = Animation.NodeAnimationRegistry.ResolveAnyByName(nt.Name);
                if (clip != null)
                    world.AddComponent(e, new Animation.NodeAnimationPlayer { Clip = clip, Time = 0f, Playing = true, Loop = true });
            }
        }

        // Advances each skinned character's animator once per frame (frame-guarded across views +
        // primitives). Called at the top of RenderShadowMaps so the pose is ready for skinned shadow
        // casting; DrawSkinnedEntities re-runs it as a fallback (no-op once already advanced).
        private static void UpdateSkinnedAnimators(ECSWorld world)
        {
            if (!world.HasAnyComponent<Animation.SkinnedMeshRenderer>()) return;
            float dt = (float)Sokol.SApp.sapp_frame_duration();
            foreach (var row in world.Query<ActiveFlag, Animation.SkinnedMeshRenderer, Transform>()
                                     .Enumerate<ActiveFlag, Animation.SkinnedMeshRenderer, Transform>())
            {
                if (!row.Item1.Value.Active) continue;
                ref readonly var smr = ref row.Item2.Value;
                if (!Animation.SkinnedCharacterRegistry.TryGet(smr.CharacterKey, out var entry)) continue;
                var anim = entry.Animator;
                if (anim != null && anim.LastUpdatedFrame != _animationFrame)
                {
                    anim.LastUpdatedFrame = _animationFrame;
                    // The character follows its first skinned mesh's playback settings (G6 A0); not playing: the pose holds.
                    if (!entry.Driven && entry.Apply(smr)) anim.UpdateAnimation(dt);   // a controller's character: posed by AnimatorSystem
                }
                RefreshJointTextureIfNeeded(entry);
            }
        }

        // Ensures a >128-bone character's joint-matrix texture exists and holds this frame's pose.
        // The upload is frame-guarded inside the entry, so calling this from both the shadow tick
        // (UpdateSkinnedAnimators) and the color tick (DrawSkinnedEntities) costs at most one upload
        // per character per frame — whichever pass runs first wins. No-op for ≤128-bone skeletons.
        private static void RefreshJointTextureIfNeeded(Animation.SkinnedCharacterRegistry.Entry entry)
        {
            if (!entry.UsesTextureSkinning) return;
            entry.EnsureJointTexture();
            entry.UploadJointMatrices(_animationFrame);
        }

        // ── GPU skinning draw path ─────────────────────────────────────────────────────────
        // Ticks each character's animator once per frame (shared across its primitives + views),
        // stages the per-character model matrix into the skinned instance buffer, then draws each
        // skinned mesh through the pbr_skinning variant (bone matrices ride in the vs_params UBO).
        private static void DrawSkinnedEntities(ECSWorld world, in Matrix4x4 viewProj,
                                                Vector3 cameraPos, PipelineFlags basePipelineFlags)
        {
            _skinnedDraws.Clear();
            float dt = (float)Sokol.SApp.sapp_frame_duration();

            foreach (var row in world.Query<ActiveFlag, Animation.SkinnedMeshRenderer, Transform>()
                                     .EnumerateWithEntities<ActiveFlag, Animation.SkinnedMeshRenderer, Transform>())
            {
                if (!row.Item1.Value.Active) continue;
                ref readonly var smr = ref row.Item2.Value;
                if (!smr.Visible) continue;
                // Resolve the live mesh + shared animator from the registry (the component holds only keys).
                if (!Animation.SkinnedCharacterRegistry.TryGet(smr.CharacterKey, out var entry)) continue;
                if (!entry.Meshes.TryGetValue(smr.PrimIndex, out var mesh) || mesh.IndexCount == 0) continue;
                ref readonly var tf = ref row.Item3.Value;

                // Advance the (possibly shared) animator exactly once per frame.
                var anim = entry.Animator;
                if (anim != null && anim.LastUpdatedFrame != _animationFrame)
                {
                    anim.LastUpdatedFrame = _animationFrame;
                    // The character follows its first skinned mesh's playback settings (G6 A0); not playing: the pose holds.
                    if (!entry.Driven && entry.Apply(smr)) anim.UpdateAnimation(dt);   // a controller's character: posed by AnimatorSystem
                }
                RefreshJointTextureIfNeeded(entry);

                _skinnedDraws.Add((smr, entry, mesh, Transform.GetWorldMatrix(world, tf)));
            }

            if (_skinnedDraws.Count == 0) return;

            // One model matrix (1 instance) per skinned mesh → the skinned instance buffer.
            _skinnedInstanceBuf.ResetStaging();
            int staged = 0;
            for (int k = 0; k < _skinnedDraws.Count; k++)
            {
                var model = _skinnedDraws[k].model;
                if (!_skinnedInstanceBuf.TryAppend(new InstanceData(in model,
                        new Vector4(1f, 1f, 1f, _skinnedDraws[k].smr.ReceivesShadows ? 1f : 0f))))
                    break;
                staged++;
            }
            if (staged == 0) return;
            int baseOff = _skinnedInstanceBuf.Flush();

            // Match the static PBR directional-shadow selection: CSM4 → skinning_csm4,
            // else a single-fit directional map → skinning_csm1, else the base skinning variant.
            bool csm4 = _csmCascadeCount == 4;
            bool csm1 = !csm4 && _hasDirectionalShadow;
            for (int k = 0; k < staged; k++)
            {
                int instByteOffset = baseOff + k * Unsafe.SizeOf<InstanceData>();
                var d = _skinnedDraws[k];
                // Morphed primitives route to the skinning+morphing variants (extra morph-texture bind +
                // weights uniform); non-morphed skinned chars keep the cheaper non-morph pipeline.
                bool morph = d.mesh.HasMorph;
                if (csm4)
                {
                    if (morph) DrawSkinnedMorphingCsm4(d.smr, d.entry, d.mesh, instByteOffset, basePipelineFlags, in viewProj, cameraPos);
                    else       DrawSkinnedCsm4        (d.smr, d.entry, d.mesh, instByteOffset, basePipelineFlags, in viewProj, cameraPos);
                }
                else if (csm1)
                {
                    if (morph) DrawSkinnedMorphingCsm1(d.smr, d.entry, d.mesh, instByteOffset, basePipelineFlags, in viewProj, cameraPos);
                    else       DrawSkinnedCsm1        (d.smr, d.entry, d.mesh, instByteOffset, basePipelineFlags, in viewProj, cameraPos);
                }
                else
                {
                    if (morph) DrawSkinnedMorphing(d.smr, d.entry, d.mesh, instByteOffset, basePipelineFlags, in viewProj, cameraPos);
                    else       DrawSkinned        (d.smr, d.entry, d.mesh, instByteOffset, basePipelineFlags, in viewProj, cameraPos);
                }
            }
        }

        /// <summary>
        /// Draws one skinned mesh through the pbr_skinning variant. Mirrors <see cref="DrawPbrGroup"/>
        /// (material + IBL + spot-shadow binding) but with the pbr_skinning uniform/binding set, a
        /// single instance, and the bone matrices uploaded into vs_params.finalBonesMatrices
        /// (use_uniform_skinning = 1). A null animator ⇒ zero bones ⇒ shader bind-pose fallback.
        /// </summary>
        private static void DrawSkinned(in Animation.SkinnedMeshRenderer smr, Animation.SkinnedCharacterRegistry.Entry entry,
                                        Resources.SkinnedMesh mesh, int instanceByteOffset,
                                        PipelineFlags basePipelineFlags, in Matrix4x4 viewProj, Vector3 cameraPos)
        {
            var mat = (_matReg.GetByKey(smr.MaterialKey) as Materials.PbrMaterial) ?? _defaultMat;

            bool blend = mat.AlphaMode == 2;
            PipelineFlags pf = basePipelineFlags;
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            if (blend)           pf |= PipelineFlags.AlphaBlend;
            sg_apply_pipeline(_shaderCache.GetPbrSkinningPipeline(pf));

            // ── VS params (+ bone matrices) ──
            // >128-bone skeletons can't fit the finalBonesMatrices[] UBO array, so their bones ride in
            // the per-character joint texture (use_uniform_skinning=0), uploaded earlier this frame by
            // RefreshJointTextureIfNeeded. Fall back to the uniform path if the texture isn't ready.
            bool useTex = entry.UsesTextureSkinning && entry.JointTextureView.id != 0;
            if (_shaderCache.CurrentLow && !useTex) return;   // LOW_TIER: no bone array — the joint texture comes next frame
            var vs = new PbrSkin.Shaders.pbr_skinning_pbr_vs_params_t
            {
                view_proj            = viewProj,
                eye_pos              = cameraPos,
                use_uniform_skinning = useTex ? 0 : 1,
            };
            if (!useTex)
            {
                var bones = entry.Animator?.GetFinalBoneMatrices();
                if (bones != null)
                {
                    int bc = Math.Min(Math.Min(entry.BoneCount, bones.Length), Animation.AnimationConstants.MAX_BONES);
                    for (int i = 0; i < bc; i++) vs.finalBonesMatrices[i] = bones[i];
                }
            }

            // ── Light params (same packing as the base PBR path) ──
            var lights = new PbrSkin.Shaders.pbr_skinning_pbr_light_params_t();
            int n = _lightBuf.Count;
            var span = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                lights.lights_data[b + 0] = span[l].PositionType;
                lights.lights_data[b + 1] = span[l].DirectionRange;
                lights.lights_data[b + 2] = span[l].ColorIntensity;
                lights.lights_data[b + 3] = span[l].SpotShadow;
            }
            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
                int sb = si * 4;
                var sm = _spotShadowViewProj[si];
                lights.spot_shadow_vp[sb + 0] = new Vector4(sm.M11, sm.M12, sm.M13, sm.M14);
                lights.spot_shadow_vp[sb + 1] = new Vector4(sm.M21, sm.M22, sm.M23, sm.M24);
                lights.spot_shadow_vp[sb + 2] = new Vector4(sm.M31, sm.M32, sm.M33, sm.M34);
                lights.spot_shadow_vp[sb + 3] = new Vector4(sm.M41, sm.M42, sm.M43, sm.M44);
            }
            // Point-light shadow VPs (cube faces; slice = slot*6 + face) — skinned point shadows.
            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
            {
                int pb = pi * 4;
                var pm = _pointShadowViewProj[pi];
                lights.point_shadow_vp[pb + 0] = new Vector4(pm.M11, pm.M12, pm.M13, pm.M14);
                lights.point_shadow_vp[pb + 1] = new Vector4(pm.M21, pm.M22, pm.M23, pm.M24);
                lights.point_shadow_vp[pb + 2] = new Vector4(pm.M31, pm.M32, pm.M33, pm.M34);
                lights.point_shadow_vp[pb + 3] = new Vector4(pm.M41, pm.M42, pm.M43, pm.M44);
            }
            lights.ambient_num = new Vector4(0f, 0f, 0f, n);

            var cam = new PbrSkin.Shaders.pbr_skinning_pbr_camera_params_t { u_Camera = cameraPos };

            bool iblActive = _environment is { IsLoaded: true };
            var ibl = new PbrSkin.Shaders.pbr_skinning_pbr_ibl_params_t
            {
                u_EnvIntensity      = iblActive ? _environment!.Intensity : 1f,
                u_AmbientParams     = _pbrAmbientParams,
                u_EnvBlurNormalized = 0f,
                u_MipCount          = iblActive ? _environment!.MipCount : 1,
                u_EnvRotation       = iblActive ? _environment!.Rotation : Matrix4x4.Identity,
                u_ViewMatrix        = Matrix4x4.Identity,
                u_ProjectionMatrix  = Matrix4x4.Identity,
                u_ModelMatrix       = Matrix4x4.Identity,
            };

            var matParams = new PbrSkin.Shaders.pbr_skinning_pbr_material_params_t
            {
                base_color_factor          = mat.BaseColorFactor,
                emissive_factor            = mat.EmissiveFactor,
                metallic_factor            = mat.MetallicFactor,
                roughness_factor           = mat.RoughnessFactor,
                has_base_color_tex         = mat.BaseColorMap.id         != 0 ? 1f : 0f,
                has_metallic_roughness_tex = mat.MetallicRoughnessMap.id != 0 ? 1f : 0f,
                has_normal_tex             = mat.NormalMap.id            != 0 ? 1f : 0f,
                has_occlusion_tex          = mat.OcclusionMap.id         != 0 ? 1f : 0f,
                has_emissive_tex           = mat.EmissiveMap.id          != 0 ? 1f : 0f,
                alpha_cutoff               = mat.AlphaCutoff,
                emissive_strength          = mat.EmissiveStrength,
                occlusion_strength         = mat.OcclusionStrength,
                ior                        = 1.5f,
                normal_map_scale           = mat.NormalMapScale,
                // KHR_texture_transform (offset/rotation/scale) + per-texture coordinate set —
                // filled from the material (was hardcoded identity, which broke tiled normal maps).
                base_color_texcoord             = mat.BaseColorTexcoord,
                base_color_tex_offset           = mat.BaseColorTexOffset,
                base_color_tex_rotation         = mat.BaseColorTexRotation,
                base_color_tex_scale            = mat.BaseColorTexScale,
                metallic_roughness_texcoord     = mat.MetallicRoughnessTexcoord,
                metallic_roughness_tex_offset   = mat.MetallicRoughnessTexOffset,
                metallic_roughness_tex_rotation = mat.MetallicRoughnessTexRotation,
                metallic_roughness_tex_scale    = mat.MetallicRoughnessTexScale,
                normal_texcoord                 = mat.NormalTexcoord,
                normal_tex_offset               = mat.NormalTexOffset,
                normal_tex_rotation             = mat.NormalTexRotation,
                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                debug_view_enabled           = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode              = PbrDebugViewMode,
                shadow_ambient_weight        = ShadowAmbientWeight,
            };

            var flags = new PbrSkin.Shaders.pbr_skinning_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,
                ambient_strength    = 0.4f,
            };

            LowTierUniforms.ApplySkinnedVs(PbrSkin.Shaders.UB_pbr_skinning_pbr_vs_params, in vs, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkin.Shaders.UB_pbr_skinning_pbr_material_params, SG_RANGE(ref matParams));
            LowTierUniforms.ApplyPbrLights(PbrSkin.Shaders.UB_pbr_skinning_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkin.Shaders.UB_pbr_skinning_pbr_ibl_params,      SG_RANGE(ref ibl));
            sg_apply_uniforms(PbrSkin.Shaders.UB_pbr_skinning_pbr_camera_params,   SG_RANGE(ref cam));
            sg_apply_uniforms(PbrSkin.Shaders.UB_pbr_skinning_pbr_rendering_flags, SG_RANGE(ref flags));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            sg_apply_bindings(ClusterBind(new sg_bindings
            {
                vertex_buffers        = { [0] = mesh.VertexBuffer, [1] = _skinnedInstanceBuf.Buffer },
                vertex_buffer_offsets = { [1] = instanceByteOffset },
                index_buffer          = mesh.IndexBuffer,
                views = {
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_BaseColorTexture]         = baseColor,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_MetallicRoughnessTexture] = metalRgh,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_NormalTexture]            = normalMap,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_OcclusionTexture]         = occlusion,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_EmissiveTexture]          = emissive,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_GGXEnvTexture]            = ggxEnv,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_LambertianEnvTexture]     = lambEnv,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_GGXLUTTexture]            = lut,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_shadow_atlas]              = _shadowAtlas.TextureView,
                    [PbrSkin.Shaders.VIEW_pbr_skinning_cube_shadow_array]         = _cubeShadows.TextureView,
                    // Joint texture: real per-character matrices when texture-skinning, else a
                    // placeholder (the binding must always be set; the uniform path ignores it).
                    [PbrSkin.Shaders.VIEW_pbr_skinning_u_jointsSampler_Tex]       = useTex ? entry.JointTextureView : _texCache.PlaceholderWhite,
                },
                samplers = {
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_BaseColorSampler]         = matSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_MetallicRoughnessSampler] = matSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_NormalSampler]            = matSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_OcclusionSampler]         = matSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_EmissiveSampler]          = matSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_GGXEnvSampler_Raw]        = cubeSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_LambertianEnvSampler_Raw] = cubeSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_GGXLUTSampler_Raw]        = lutSmp,
                    [PbrSkin.Shaders.SMP_pbr_skinning_shadow_atlas_smp]           = _shadowSampler,
                    [PbrSkin.Shaders.SMP_pbr_skinning_cube_shadow_array_smp]      = _cubeShadowSampler,
                    [PbrSkin.Shaders.SMP_pbr_skinning_u_jointsSampler_Smp]        = _jointSampler,
                },
            }));

            sg_draw(0u, (uint)mesh.IndexCount, 1u);
            _stats.DrawCalls++;
        }

        /// <summary>
        /// Skinned draw through the pbr_skinning_csm4 variant — like <see cref="DrawSkinned"/> but the
        /// surface ALSO receives the 4-cascade directional shadow (csm_vp + split depths + camera view
        /// for cascade selection), matching what <see cref="DrawPbrCsm4Group"/> does for static meshes.
        /// (Point shadows are absent in the skinning variant — binding 11 is the joints texture.)
        /// </summary>
        private static void DrawSkinnedCsm4(in Animation.SkinnedMeshRenderer smr, Animation.SkinnedCharacterRegistry.Entry entry,
                                            Resources.SkinnedMesh mesh, int instanceByteOffset,
                                            PipelineFlags basePipelineFlags, in Matrix4x4 viewProj, Vector3 cameraPos)
        {
            var mat = (_matReg.GetByKey(smr.MaterialKey) as Materials.PbrMaterial) ?? _defaultMat;

            bool blend = mat.AlphaMode == 2;
            PipelineFlags pf = basePipelineFlags;
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            if (blend)           pf |= PipelineFlags.AlphaBlend;
            sg_apply_pipeline(_shaderCache.GetPbrSkinningCsm4Pipeline(pf));

            // >128-bone skeletons take the joint-texture path (see DrawSkinned for the rationale).
            bool useTex = entry.UsesTextureSkinning && entry.JointTextureView.id != 0;
            if (_shaderCache.CurrentLow && !useTex) return;   // LOW_TIER: no bone array — the joint texture comes next frame
            var vs = new PbrSkinCsm4.Shaders.pbr_skinning_csm4_pbr_vs_params_t
            {
                view_proj            = viewProj,
                eye_pos              = cameraPos,
                use_uniform_skinning = useTex ? 0 : 1,
            };
            vs.csm_vp[0] = _csmCascadeVP[0];
            vs.csm_vp[1] = _csmCascadeVP[1];
            vs.csm_vp[2] = _csmCascadeVP[2];
            vs.csm_vp[3] = _csmCascadeVP[3];
            if (!useTex)
            {
                var bones = entry.Animator?.GetFinalBoneMatrices();
                if (bones != null)
                {
                    int bc = Math.Min(Math.Min(entry.BoneCount, bones.Length), Animation.AnimationConstants.MAX_BONES);
                    for (int i = 0; i < bc; i++) vs.finalBonesMatrices[i] = bones[i];
                }
            }

            var lights = new PbrSkinCsm4.Shaders.pbr_skinning_csm4_pbr_light_params_t();
            int n = _lightBuf.Count;
            var span = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                lights.lights_data[b + 0] = span[l].PositionType;
                lights.lights_data[b + 1] = span[l].DirectionRange;
                lights.lights_data[b + 2] = span[l].ColorIntensity;
                lights.lights_data[b + 3] = span[l].SpotShadow;
            }
            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
