                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                debug_view_enabled           = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode              = PbrDebugViewMode,
                shadow_ambient_weight        = ShadowAmbientWeight,
            };

            var flags = new PbrSkinCsm4.Shaders.pbr_skinning_csm4_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,
                ambient_strength    = 0.4f,
            };

            int pcf = ShadowQuality >= 2 ? 25 : (ShadowQuality >= 1 ? 9 : 1);
            var csm = new PbrSkinCsm4.Shaders.pbr_skinning_csm4_pbr_csm_params_t
            {
                csm_split_depths = _csmSplitDepths,
                csm_bias         = CsmBiasForBackend(),
                csm_blend_band   = 0f,
                csm_pcf_taps     = pcf,
            };

            LowTierUniforms.ApplySkinnedVs(PbrSkinCsm4.Shaders.UB_pbr_skinning_csm4_pbr_vs_params, in vs, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkinCsm4.Shaders.UB_pbr_skinning_csm4_pbr_material_params, SG_RANGE(ref matParams));
