            int pcf = ShadowQuality >= 2 ? 25 : (ShadowQuality >= 1 ? 9 : 1);
            var csm = new PbrSkinMorphCsm1.Shaders.pbr_skinning_morphing_csm1_pbr_csm_params_t
            {
