                csm_bias         = CsmBiasForBackend(),
                csm_blend_band   = 0f,
                csm_pcf_taps     = pcf,
            };

            LowTierUniforms.ApplySkinnedVs(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_vs_params, in vs, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_material_params, SG_RANGE(ref matParams));
            LowTierUniforms.ApplyPbrLights(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_ibl_params,      SG_RANGE(ref ibl));
            sg_apply_uniforms(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_camera_params,   SG_RANGE(ref cam));
            sg_apply_uniforms(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_rendering_flags, SG_RANGE(ref flags));
            sg_apply_uniforms(PbrSkinMorphCsm1.Shaders.UB_pbr_skinning_morphing_csm1_pbr_csm_params,      SG_RANGE(ref csm));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            sg_apply_bindings(ClusterBind(new sg_bindings
            {
                vertex_buffers        = { [0] = mesh.VertexBuffer, [1] = _skinnedInstanceBuf.Buffer },
                vertex_buffer_offsets = { [1] = instanceByteOffset },
                index_buffer          = mesh.IndexBuffer,
                views = {
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_BaseColorTexture]         = baseColor,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_MetallicRoughnessTexture] = metalRgh,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_NormalTexture]            = normalMap,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_OcclusionTexture]         = occlusion,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_EmissiveTexture]          = emissive,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_GGXEnvTexture]            = ggxEnv,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_LambertianEnvTexture]     = lambEnv,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_GGXLUTTexture]            = lut,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_shadow_atlas]              = _shadowAtlas.TextureView,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_cube_shadow_array]         = _cubeShadows.TextureView,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_jointsSampler_Tex]       = useTex ? entry.JointTextureView : _texCache.PlaceholderWhite,
                    [PbrSkinMorphCsm1.Shaders.VIEW_pbr_skinning_morphing_csm1_u_MorphTargetsSampler_Tex] = mesh.MorphView,
                },
                samplers = {
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_BaseColorSampler]         = matSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_MetallicRoughnessSampler] = matSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_NormalSampler]            = matSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_OcclusionSampler]         = matSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_EmissiveSampler]          = matSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_GGXEnvSampler_Raw]        = cubeSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_LambertianEnvSampler_Raw] = cubeSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_GGXLUTSampler_Raw]        = lutSmp,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_shadow_atlas_smp]           = _shadowSampler,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_cube_shadow_array_smp]      = _cubeShadowSampler,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_jointsSampler_Smp]        = _jointSampler,
                    [PbrSkinMorphCsm1.Shaders.SMP_pbr_skinning_morphing_csm1_u_MorphTargetsSampler_Smp]  = _jointSampler,
                },
            }));

            sg_draw(0u, (uint)mesh.IndexCount, 1u);
            _stats.DrawCalls++;
        }

        /// <summary>Skinning + morph + 4-cascade CSM draw. Mirrors <see cref="DrawSkinnedCsm4"/>.</summary>
        private static void DrawSkinnedMorphingCsm4(in Animation.SkinnedMeshRenderer smr, Animation.SkinnedCharacterRegistry.Entry entry,
                                                    Resources.SkinnedMesh mesh, int instanceByteOffset,
                                                    PipelineFlags basePipelineFlags, in Matrix4x4 viewProj, Vector3 cameraPos)
        {
            var mat = (_matReg.GetByKey(smr.MaterialKey) as Materials.PbrMaterial) ?? _defaultMat;

            bool blend = mat.AlphaMode == 2;
            PipelineFlags pf = basePipelineFlags;
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            if (blend)           pf |= PipelineFlags.AlphaBlend;
            sg_apply_pipeline(_shaderCache.GetPbrSkinMorphCsm4Pipeline(pf));

            bool useTex = entry.UsesTextureSkinning && entry.JointTextureView.id != 0;
            if (_shaderCache.CurrentLow && !useTex) return;   // LOW_TIER: no bone array — the joint texture comes next frame
            var vs = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_vs_params_t
            {
                view_proj            = viewProj,
                eye_pos              = cameraPos,
                use_uniform_skinning = useTex ? 0 : 1,
            };
            vs.csm_vp[0] = _csmCascadeVP[0];
            vs.csm_vp[1] = _csmCascadeVP[1];
            vs.csm_vp[2] = _csmCascadeVP[2];
            vs.csm_vp[3] = _csmCascadeVP[3];
            ResolveMorphWeights(entry, mesh, out var mw0, out var mw1);
            vs.u_morphWeights[0] = mw0;
            vs.u_morphWeights[1] = mw1;
            if (!useTex)
            {
                var bones = entry.Animator?.GetFinalBoneMatrices();
                if (bones != null)
                {
                    int bc = Math.Min(Math.Min(entry.BoneCount, bones.Length), Animation.AnimationConstants.MAX_BONES);
                    for (int i = 0; i < bc; i++) vs.finalBonesMatrices[i] = bones[i];
                }
            }

            var lights = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_light_params_t();
            int n = _lightBuf.Count;
            var span = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                lights.lights_data[b + 0] = span[l].PositionType;
                lights.lights_data[b + 1] = span[l].DirectionRange;
                lights.lights_data[b + 2] = span[l].ColorIntensity;
                lights.lights_data[b + 3] = span[l].SpotShadow;
            }
            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
                int sb = si * 4;
                var sm = _spotShadowViewProj[si];
                lights.spot_shadow_vp[sb + 0] = new Vector4(sm.M11, sm.M12, sm.M13, sm.M14);
                lights.spot_shadow_vp[sb + 1] = new Vector4(sm.M21, sm.M22, sm.M23, sm.M24);
                lights.spot_shadow_vp[sb + 2] = new Vector4(sm.M31, sm.M32, sm.M33, sm.M34);
                lights.spot_shadow_vp[sb + 3] = new Vector4(sm.M41, sm.M42, sm.M43, sm.M44);
            }
            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
            {
                int pb = pi * 4;
                var pm = _pointShadowViewProj[pi];
                lights.point_shadow_vp[pb + 0] = new Vector4(pm.M11, pm.M12, pm.M13, pm.M14);
                lights.point_shadow_vp[pb + 1] = new Vector4(pm.M21, pm.M22, pm.M23, pm.M24);
                lights.point_shadow_vp[pb + 2] = new Vector4(pm.M31, pm.M32, pm.M33, pm.M34);
                lights.point_shadow_vp[pb + 3] = new Vector4(pm.M41, pm.M42, pm.M43, pm.M44);
            }
            lights.ambient_num = new Vector4(0f, 0f, 0f, n);

            var cam = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_camera_params_t { u_Camera = cameraPos };

            bool iblActive = _environment is { IsLoaded: true };
            var ibl = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_ibl_params_t
            {
                u_EnvIntensity      = iblActive ? _environment!.Intensity : 1f,
                u_AmbientParams     = _pbrAmbientParams,
                u_EnvBlurNormalized = 0f,
                u_MipCount          = iblActive ? _environment!.MipCount : 1,
                u_EnvRotation       = iblActive ? _environment!.Rotation : Matrix4x4.Identity,
                u_ViewMatrix        = _csmCameraView,
                u_ProjectionMatrix  = Matrix4x4.Identity,
                u_ModelMatrix       = Matrix4x4.Identity,
            };

            var matParams = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_material_params_t
            {
                base_color_factor          = mat.BaseColorFactor,
                emissive_factor            = mat.EmissiveFactor,
                metallic_factor            = mat.MetallicFactor,
                roughness_factor           = mat.RoughnessFactor,
                has_base_color_tex         = mat.BaseColorMap.id         != 0 ? 1f : 0f,
                has_metallic_roughness_tex = mat.MetallicRoughnessMap.id != 0 ? 1f : 0f,
                has_normal_tex             = mat.NormalMap.id            != 0 ? 1f : 0f,
                has_occlusion_tex          = mat.OcclusionMap.id         != 0 ? 1f : 0f,
                has_emissive_tex           = mat.EmissiveMap.id          != 0 ? 1f : 0f,
                alpha_cutoff               = mat.AlphaCutoff,
                emissive_strength          = mat.EmissiveStrength,
                occlusion_strength         = mat.OcclusionStrength,
                ior                        = 1.5f,
                normal_map_scale           = mat.NormalMapScale,
                // KHR_texture_transform (offset/rotation/scale) + per-texture coordinate set —
                // filled from the material (was hardcoded identity, which broke tiled normal maps).
                base_color_texcoord             = mat.BaseColorTexcoord,
                base_color_tex_offset           = mat.BaseColorTexOffset,
                base_color_tex_rotation         = mat.BaseColorTexRotation,
                base_color_tex_scale            = mat.BaseColorTexScale,
                metallic_roughness_texcoord     = mat.MetallicRoughnessTexcoord,
                metallic_roughness_tex_offset   = mat.MetallicRoughnessTexOffset,
                metallic_roughness_tex_rotation = mat.MetallicRoughnessTexRotation,
                metallic_roughness_tex_scale    = mat.MetallicRoughnessTexScale,
                normal_texcoord                 = mat.NormalTexcoord,
                normal_tex_offset               = mat.NormalTexOffset,
                normal_tex_rotation             = mat.NormalTexRotation,
                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                debug_view_enabled           = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode              = PbrDebugViewMode,
                shadow_ambient_weight        = ShadowAmbientWeight,
            };

            var flags = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,
                ambient_strength    = 0.4f,
            };

            int pcf = ShadowQuality >= 2 ? 25 : (ShadowQuality >= 1 ? 9 : 1);
            var csm = new PbrSkinMorphCsm4.Shaders.pbr_skinning_morphing_csm4_pbr_csm_params_t
            {
                csm_split_depths = _csmSplitDepths,
                csm_bias         = CsmBiasForBackend(),
                csm_blend_band   = 0f,
                csm_pcf_taps     = pcf,
            };

            LowTierUniforms.ApplySkinnedVs(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_vs_params, in vs, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_material_params, SG_RANGE(ref matParams));
            LowTierUniforms.ApplyPbrLights(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_ibl_params,      SG_RANGE(ref ibl));
            sg_apply_uniforms(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_camera_params,   SG_RANGE(ref cam));
            sg_apply_uniforms(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_rendering_flags, SG_RANGE(ref flags));
            sg_apply_uniforms(PbrSkinMorphCsm4.Shaders.UB_pbr_skinning_morphing_csm4_pbr_csm_params,      SG_RANGE(ref csm));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            sg_apply_bindings(ClusterBind(new sg_bindings
            {
                vertex_buffers        = { [0] = mesh.VertexBuffer, [1] = _skinnedInstanceBuf.Buffer },
                vertex_buffer_offsets = { [1] = instanceByteOffset },
                index_buffer          = mesh.IndexBuffer,
                views = {
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_BaseColorTexture]         = baseColor,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_MetallicRoughnessTexture] = metalRgh,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_NormalTexture]            = normalMap,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_OcclusionTexture]         = occlusion,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_EmissiveTexture]          = emissive,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_GGXEnvTexture]            = ggxEnv,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_LambertianEnvTexture]     = lambEnv,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_GGXLUTTexture]            = lut,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_shadow_atlas]              = _shadowAtlas.TextureView,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_cube_shadow_array]         = _cubeShadows.TextureView,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_jointsSampler_Tex]       = useTex ? entry.JointTextureView : _texCache.PlaceholderWhite,
                    [PbrSkinMorphCsm4.Shaders.VIEW_pbr_skinning_morphing_csm4_u_MorphTargetsSampler_Tex] = mesh.MorphView,
                },
                samplers = {
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_BaseColorSampler]         = matSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_MetallicRoughnessSampler] = matSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_NormalSampler]            = matSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_OcclusionSampler]         = matSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_EmissiveSampler]          = matSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_GGXEnvSampler_Raw]        = cubeSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_LambertianEnvSampler_Raw] = cubeSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_GGXLUTSampler_Raw]        = lutSmp,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_shadow_atlas_smp]           = _shadowSampler,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_cube_shadow_array_smp]      = _cubeShadowSampler,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_jointsSampler_Smp]        = _jointSampler,
                    [PbrSkinMorphCsm4.Shaders.SMP_pbr_skinning_morphing_csm4_u_MorphTargetsSampler_Smp]  = _jointSampler,
                },
            }));

            sg_draw(0u, (uint)mesh.IndexCount, 1u);
            _stats.DrawCalls++;
        }

        /// <summary>
        /// Draws a PBR group through the 1-cascade-CSM variant so the surface receives the
        /// directional shadow already rendered to atlas slice 0. Mirrors <see cref="DrawPbrGroup"/>
        /// but with the pbr_csm1 uniform/binding set, plus the CSM params + shadow atlas. Builds
        /// its own (csm1-typed) blocks from the same source data.
        /// </summary>
        private static void DrawPbrCsm1Group(
            PbrMaterial mat, MeshResource mesh, int groupSize, int instanceByteOffset,
            PipelineFlags basePipelineFlags, in Matrix4x4 viewProj, Vector3 cameraPos)
        {
            bool blend = mat.AlphaMode == 2;
            PipelineFlags pf = basePipelineFlags;
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            if (blend)           pf |= PipelineFlags.AlphaBlend;
            sg_apply_pipeline(_shaderCache.GetPbrCsm1Pipeline(pf));

            var vs = new Csm1.Shaders.pbr_csm1_pbr_vs_params_t
            {
                view_proj            = viewProj,
                eye_pos              = cameraPos,
                use_uniform_skinning = 1,
            };
            vs.csm_vp[0] = _directionalShadowViewProj;   // cascade 0 = the slice-0 directional map

            var lights = new Csm1.Shaders.pbr_csm1_pbr_light_params_t();
            int n = _lightBuf.Count;
            var span = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                lights.lights_data[b + 0] = span[l].PositionType;
                lights.lights_data[b + 1] = span[l].DirectionRange;
                lights.lights_data[b + 2] = span[l].ColorIntensity;
                lights.lights_data[b + 3] = span[l].SpotShadow;
            }
            // Spot-light shadow VPs (atlas slices 4-11) so PBR surfaces receive spot shadows.
            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
                int sb = si * 4;
                var sm = _spotShadowViewProj[si];
                lights.spot_shadow_vp[sb + 0] = new Vector4(sm.M11, sm.M12, sm.M13, sm.M14);
                lights.spot_shadow_vp[sb + 1] = new Vector4(sm.M21, sm.M22, sm.M23, sm.M24);
                lights.spot_shadow_vp[sb + 2] = new Vector4(sm.M31, sm.M32, sm.M33, sm.M34);
                lights.spot_shadow_vp[sb + 3] = new Vector4(sm.M41, sm.M42, sm.M43, sm.M44);
            }
            // Point-light shadow VPs (cube faces; slice = slot*6 + face) for PBR point shadows.
            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
            {
                int pb = pi * 4;
                var pm = _pointShadowViewProj[pi];
                lights.point_shadow_vp[pb + 0] = new Vector4(pm.M11, pm.M12, pm.M13, pm.M14);
                lights.point_shadow_vp[pb + 1] = new Vector4(pm.M21, pm.M22, pm.M23, pm.M24);
                lights.point_shadow_vp[pb + 2] = new Vector4(pm.M31, pm.M32, pm.M33, pm.M34);
                lights.point_shadow_vp[pb + 3] = new Vector4(pm.M41, pm.M42, pm.M43, pm.M44);
            }
            lights.ambient_num = new Vector4(0f, 0f, 0f, n);

            var cam = new Csm1.Shaders.pbr_csm1_pbr_camera_params_t { u_Camera = cameraPos };

            bool iblActive = _environment is { IsLoaded: true };
            var ibl = new Csm1.Shaders.pbr_csm1_pbr_ibl_params_t
            {
                u_EnvIntensity      = iblActive ? _environment!.Intensity : 1f,
                u_AmbientParams     = _pbrAmbientParams,
                u_EnvBlurNormalized = 0f,
                u_MipCount          = iblActive ? _environment!.MipCount : 1,
                u_EnvRotation       = iblActive ? _environment!.Rotation : Matrix4x4.Identity,
                u_ViewMatrix        = Matrix4x4.Identity,
                u_ProjectionMatrix  = Matrix4x4.Identity,
                u_ModelMatrix       = Matrix4x4.Identity,
            };

            var matParams = new Csm1.Shaders.pbr_csm1_pbr_material_params_t
            {
                base_color_factor          = mat.BaseColorFactor,
                emissive_factor            = mat.EmissiveFactor,
                metallic_factor            = mat.MetallicFactor,
                roughness_factor           = mat.RoughnessFactor,
                has_base_color_tex         = mat.BaseColorMap.id         != 0 ? 1f : 0f,
                has_metallic_roughness_tex = mat.MetallicRoughnessMap.id != 0 ? 1f : 0f,
                has_normal_tex             = mat.NormalMap.id            != 0 ? 1f : 0f,
                has_occlusion_tex          = mat.OcclusionMap.id         != 0 ? 1f : 0f,
                has_emissive_tex           = mat.EmissiveMap.id          != 0 ? 1f : 0f,
                alpha_cutoff               = mat.AlphaCutoff,
                emissive_strength          = mat.EmissiveStrength,
                occlusion_strength         = mat.OcclusionStrength,
                ior                        = 1.5f,
                normal_map_scale           = mat.NormalMapScale,
                // KHR_texture_transform (offset/rotation/scale) + per-texture coordinate set —
                // filled from the material (was hardcoded identity, which broke tiled normal maps).
                base_color_texcoord             = mat.BaseColorTexcoord,
                base_color_tex_offset           = mat.BaseColorTexOffset,
                base_color_tex_rotation         = mat.BaseColorTexRotation,
                base_color_tex_scale            = mat.BaseColorTexScale,
                metallic_roughness_texcoord     = mat.MetallicRoughnessTexcoord,
                metallic_roughness_tex_offset   = mat.MetallicRoughnessTexOffset,
                metallic_roughness_tex_rotation = mat.MetallicRoughnessTexRotation,
                metallic_roughness_tex_scale    = mat.MetallicRoughnessTexScale,
                normal_texcoord                 = mat.NormalTexcoord,
                normal_tex_offset               = mat.NormalTexOffset,
                normal_tex_rotation             = mat.NormalTexRotation,
                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                debug_view_enabled           = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode              = PbrDebugViewMode,
                shadow_ambient_weight        = ShadowAmbientWeight,
            };

            var flags = new Csm1.Shaders.pbr_csm1_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,
                ambient_strength    = 0.4f,
            };

            int pcf = ShadowQuality >= 2 ? 25 : (ShadowQuality >= 1 ? 9 : 1);
            var csm = new Csm1.Shaders.pbr_csm1_pbr_csm_params_t
            {
                csm_split_depths = new Vector4(1e9f, 1e9f, 1e9f, 1e9f), // CSM1 → always cascade 0
                csm_bias         = CsmBiasForBackend(),
                csm_blend_band   = 0f,
                csm_pcf_taps     = pcf,
            };

            sg_apply_uniforms(Csm1.Shaders.UB_pbr_csm1_pbr_vs_params,       SG_RANGE(ref vs));
            sg_apply_uniforms(Csm1.Shaders.UB_pbr_csm1_pbr_material_params, SG_RANGE(ref matParams));
            LowTierUniforms.ApplyPbrLights(Csm1.Shaders.UB_pbr_csm1_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(Csm1.Shaders.UB_pbr_csm1_pbr_ibl_params,      SG_RANGE(ref ibl));
            sg_apply_uniforms(Csm1.Shaders.UB_pbr_csm1_pbr_camera_params,   SG_RANGE(ref cam));
            sg_apply_uniforms(Csm1.Shaders.UB_pbr_csm1_pbr_rendering_flags, SG_RANGE(ref flags));
            sg_apply_uniforms(Csm1.Shaders.UB_pbr_csm1_pbr_csm_params,      SG_RANGE(ref csm));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            foreach (MeshSubResource sub in mesh.SubMeshes)
            {
                if (sub.IndexCount == 0 || sub.VertexBuffer.id == 0 || sub.IndexBuffer.id == 0)
                    continue;

                sg_apply_bindings(ClusterBind(new sg_bindings
                {
                    vertex_buffers        = { [0] = sub.VertexBuffer, [1] = _instanceBuf.Buffer },
                    vertex_buffer_offsets = { [1] = instanceByteOffset },
                    index_buffer          = sub.IndexBuffer,
                    views = {
                        [Csm1.Shaders.VIEW_pbr_csm1_u_BaseColorTexture]         = baseColor,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_MetallicRoughnessTexture] = metalRgh,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_NormalTexture]            = normalMap,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_OcclusionTexture]         = occlusion,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_EmissiveTexture]          = emissive,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_GGXEnvTexture]            = ggxEnv,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_LambertianEnvTexture]     = lambEnv,
                        [Csm1.Shaders.VIEW_pbr_csm1_u_GGXLUTTexture]            = lut,
                        [Csm1.Shaders.VIEW_pbr_csm1_shadow_atlas]               = _shadowAtlas.TextureView,
                        [Csm1.Shaders.VIEW_pbr_csm1_cube_shadow_array]          = _cubeShadows.TextureView,
                    },
                    samplers = {
                        [Csm1.Shaders.SMP_pbr_csm1_u_BaseColorSampler]         = matSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_MetallicRoughnessSampler] = matSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_NormalSampler]            = matSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_OcclusionSampler]         = matSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_EmissiveSampler]          = matSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_GGXEnvSampler_Raw]        = cubeSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_LambertianEnvSampler_Raw] = cubeSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_u_GGXLUTSampler_Raw]        = lutSmp,
                        [Csm1.Shaders.SMP_pbr_csm1_shadow_atlas_smp]           = _shadowSampler,
                        [Csm1.Shaders.SMP_pbr_csm1_cube_shadow_array_smp]      = _cubeShadowSampler,
                    },
                }));

                sg_draw(0u, (uint)sub.IndexCount, (uint)groupSize);
                _stats.DrawCalls++;
            }
        }

        // Constant depth bias for the shadow comparison, tuned per backend (plan §CSM table).
        private static float CsmBiasForBackend() => sg_query_backend() switch
        {
            Sokol.SG.sg_backend.SG_BACKEND_METAL_MACOS or
            Sokol.SG.sg_backend.SG_BACKEND_METAL_IOS or
            Sokol.SG.sg_backend.SG_BACKEND_METAL_SIMULATOR or
            Sokol.SG.sg_backend.SG_BACKEND_D3D11   => 0.0005f,
            Sokol.SG.sg_backend.SG_BACKEND_GLCORE  => 0.0008f,
            Sokol.SG.sg_backend.SG_BACKEND_GLES3   => 0.0015f,
            _                                      => 0.001f,
        };

        /// <summary>
        /// Draws a PBR group through the 4-cascade-CSM variant. Mirrors <see cref="DrawPbrCsm1Group"/>
        /// but binds all four cascade VPs (atlas slices 0-3), the PSSM split depths, and the camera
        /// view matrix (for per-fragment cascade selection). Uses the same shadow atlas + comparison
        /// sampler. State comes from the CSM cascades computed in <see cref="CollectLightsAndShadows"/>.
        /// </summary>
        private static void DrawPbrCsm4Group(
            PbrMaterial mat, MeshResource mesh, int groupSize, int instanceByteOffset,
            PipelineFlags basePipelineFlags, in Matrix4x4 viewProj, Vector3 cameraPos)
        {
            bool blend = mat.AlphaMode == 2;
            PipelineFlags pf = basePipelineFlags;
            if (mat.DoubleSided) pf |= PipelineFlags.DoubleSided;
            if (blend)           pf |= PipelineFlags.AlphaBlend;
            sg_apply_pipeline(_shaderCache.GetPbrCsm4Pipeline(pf));

            var vs = new Csm4.Shaders.pbr_csm4_pbr_vs_params_t
            {
                view_proj            = viewProj,
                eye_pos              = cameraPos,
                use_uniform_skinning = 1,
            };
            vs.csm_vp[0] = _csmCascadeVP[0];
            vs.csm_vp[1] = _csmCascadeVP[1];
            vs.csm_vp[2] = _csmCascadeVP[2];
            vs.csm_vp[3] = _csmCascadeVP[3];

            var lights = new Csm4.Shaders.pbr_csm4_pbr_light_params_t();
            int n = _lightBuf.Count;
            var span = _lightBuf.ActiveSpan;
            for (int l = 0; l < n; l++)
            {
                int b = l * 4;
                lights.lights_data[b + 0] = span[l].PositionType;
                lights.lights_data[b + 1] = span[l].DirectionRange;
                lights.lights_data[b + 2] = span[l].ColorIntensity;
                lights.lights_data[b + 3] = span[l].SpotShadow;
            }
            // Spot-light shadow VPs (atlas slices 4-11) so PBR surfaces receive spot shadows.
            for (int si = 0; si < ShadowAtlas.SpotSlices; si++)
            {
                int sb = si * 4;
                var sm = _spotShadowViewProj[si];
                lights.spot_shadow_vp[sb + 0] = new Vector4(sm.M11, sm.M12, sm.M13, sm.M14);
                lights.spot_shadow_vp[sb + 1] = new Vector4(sm.M21, sm.M22, sm.M23, sm.M24);
                lights.spot_shadow_vp[sb + 2] = new Vector4(sm.M31, sm.M32, sm.M33, sm.M34);
                lights.spot_shadow_vp[sb + 3] = new Vector4(sm.M41, sm.M42, sm.M43, sm.M44);
            }
            // Point-light shadow VPs (cube faces; slice = slot*6 + face) for PBR point shadows.
            for (int pi = 0; pi < _pointShadowViewProj.Length; pi++)
            {
                int pb = pi * 4;
                var pm = _pointShadowViewProj[pi];
                lights.point_shadow_vp[pb + 0] = new Vector4(pm.M11, pm.M12, pm.M13, pm.M14);
                lights.point_shadow_vp[pb + 1] = new Vector4(pm.M21, pm.M22, pm.M23, pm.M24);
                lights.point_shadow_vp[pb + 2] = new Vector4(pm.M31, pm.M32, pm.M33, pm.M34);
                lights.point_shadow_vp[pb + 3] = new Vector4(pm.M41, pm.M42, pm.M43, pm.M44);
            }
            lights.ambient_num = new Vector4(0f, 0f, 0f, n);

            var cam = new Csm4.Shaders.pbr_csm4_pbr_camera_params_t { u_Camera = cameraPos };

            bool iblActive = _environment is { IsLoaded: true };
            var ibl = new Csm4.Shaders.pbr_csm4_pbr_ibl_params_t
            {
                u_EnvIntensity      = iblActive ? _environment!.Intensity : 1f,
                u_AmbientParams     = _pbrAmbientParams,
                u_EnvBlurNormalized = 0f,
                u_MipCount          = iblActive ? _environment!.MipCount : 1,
                u_EnvRotation       = iblActive ? _environment!.Rotation : Matrix4x4.Identity,
                u_ViewMatrix        = _csmCameraView,   // cascade selection by view-space depth
                u_ProjectionMatrix  = Matrix4x4.Identity,
                u_ModelMatrix       = Matrix4x4.Identity,
            };

            var matParams = new Csm4.Shaders.pbr_csm4_pbr_material_params_t
            {
                base_color_factor          = mat.BaseColorFactor,
                emissive_factor            = mat.EmissiveFactor,
                metallic_factor            = mat.MetallicFactor,
                roughness_factor           = mat.RoughnessFactor,
                has_base_color_tex         = mat.BaseColorMap.id         != 0 ? 1f : 0f,
                has_metallic_roughness_tex = mat.MetallicRoughnessMap.id != 0 ? 1f : 0f,
                has_normal_tex             = mat.NormalMap.id            != 0 ? 1f : 0f,
                has_occlusion_tex          = mat.OcclusionMap.id         != 0 ? 1f : 0f,
                has_emissive_tex           = mat.EmissiveMap.id          != 0 ? 1f : 0f,
                alpha_cutoff               = mat.AlphaCutoff,
                emissive_strength          = mat.EmissiveStrength,
                occlusion_strength         = mat.OcclusionStrength,
                ior                        = 1.5f,
                normal_map_scale           = mat.NormalMapScale,
                // KHR_texture_transform (offset/rotation/scale) + per-texture coordinate set —
                // filled from the material (was hardcoded identity, which broke tiled normal maps).
                base_color_texcoord             = mat.BaseColorTexcoord,
                base_color_tex_offset           = mat.BaseColorTexOffset,
                base_color_tex_rotation         = mat.BaseColorTexRotation,
                base_color_tex_scale            = mat.BaseColorTexScale,
                metallic_roughness_texcoord     = mat.MetallicRoughnessTexcoord,
                metallic_roughness_tex_offset   = mat.MetallicRoughnessTexOffset,
                metallic_roughness_tex_rotation = mat.MetallicRoughnessTexRotation,
                metallic_roughness_tex_scale    = mat.MetallicRoughnessTexScale,
                normal_texcoord                 = mat.NormalTexcoord,
                normal_tex_offset               = mat.NormalTexOffset,
                normal_tex_rotation             = mat.NormalTexRotation,
                normal_tex_scale                = mat.NormalTexScale,
                occlusion_texcoord              = mat.OcclusionTexcoord,
                occlusion_tex_offset            = mat.OcclusionTexOffset,
                occlusion_tex_rotation          = mat.OcclusionTexRotation,
                occlusion_tex_scale             = mat.OcclusionTexScale,
                emissive_texcoord               = mat.EmissiveTexcoord,
                emissive_tex_offset             = mat.EmissiveTexOffset,
                emissive_tex_rotation           = mat.EmissiveTexRotation,
                emissive_tex_scale              = mat.EmissiveTexScale,
                clearcoat_factor                = mat.ClearcoatFactor,
                clearcoat_roughness             = mat.ClearcoatRoughness,
                debug_view_enabled           = PbrDebugViewMode != 0 ? 1f : 0f,
                debug_view_mode              = PbrDebugViewMode,
                shadow_ambient_weight        = ShadowAmbientWeight,
            };

            var flags = new Csm4.Shaders.pbr_csm4_pbr_rendering_flags_t
            {
                use_ibl             = iblActive ? 1 : 0,
                use_punctual_lights = 1,
                alphamode           = mat.AlphaMode,
                linear_output       = _hdrPass ? 1 : 0,
                tonemap_type        = FallbackType,
                tonemap_exposure    = FallbackExposure,
                ambient_strength    = 0.4f,
            };

            int pcf = ShadowQuality >= 2 ? 25 : (ShadowQuality >= 1 ? 9 : 1);
            var csm = new Csm4.Shaders.pbr_csm4_pbr_csm_params_t
            {
                csm_split_depths = _csmSplitDepths,
                csm_bias         = CsmBiasForBackend(),
                csm_blend_band   = 0f,
                csm_pcf_taps     = pcf,
            };

            sg_apply_uniforms(Csm4.Shaders.UB_pbr_csm4_pbr_vs_params,       SG_RANGE(ref vs));
            sg_apply_uniforms(Csm4.Shaders.UB_pbr_csm4_pbr_material_params, SG_RANGE(ref matParams));
            LowTierUniforms.ApplyPbrLights(Csm4.Shaders.UB_pbr_csm4_pbr_light_params, in lights, _shaderCache.CurrentLow);
            sg_apply_uniforms(Csm4.Shaders.UB_pbr_csm4_pbr_ibl_params,      SG_RANGE(ref ibl));
            sg_apply_uniforms(Csm4.Shaders.UB_pbr_csm4_pbr_camera_params,   SG_RANGE(ref cam));
            sg_apply_uniforms(Csm4.Shaders.UB_pbr_csm4_pbr_rendering_flags, SG_RANGE(ref flags));
            sg_apply_uniforms(Csm4.Shaders.UB_pbr_csm4_pbr_csm_params,      SG_RANGE(ref csm));

            sg_view baseColor = mat.BaseColorMap.id         != 0 ? mat.BaseColorMap         : _texCache.PlaceholderWhite;
            sg_view metalRgh  = mat.MetallicRoughnessMap.id != 0 ? mat.MetallicRoughnessMap : _texCache.PlaceholderWhite;
            sg_view normalMap = mat.NormalMap.id            != 0 ? mat.NormalMap            : _texCache.PlaceholderNormal;
            sg_view occlusion = mat.OcclusionMap.id         != 0 ? mat.OcclusionMap         : _texCache.PlaceholderWhite;
            sg_view emissive  = mat.EmissiveMap.id          != 0 ? mat.EmissiveMap          : _texCache.PlaceholderBlack;
            sg_view ggxEnv    = iblActive ? _environment!.SpecularCubeView : _texCache.PlaceholderCube;
            sg_view lambEnv   = iblActive ? _environment!.DiffuseCubeView  : _texCache.PlaceholderCube;
            sg_view lut       = iblActive ? _environment!.GgxLutView        : _texCache.PlaceholderWhite;
            sg_sampler matSmp  = mat.Sampler.id != 0 ? mat.Sampler : _texCache.DefaultSampler;
            sg_sampler cubeSmp = iblActive ? _environment!.CubeSampler : _texCache.DefaultSampler;
            sg_sampler lutSmp  = iblActive ? _environment!.LutSampler  : _texCache.DefaultSampler;

            foreach (MeshSubResource sub in mesh.SubMeshes)
            {
                if (sub.IndexCount == 0 || sub.VertexBuffer.id == 0 || sub.IndexBuffer.id == 0)
                    continue;

                sg_apply_bindings(ClusterBind(new sg_bindings
                {
                    vertex_buffers        = { [0] = sub.VertexBuffer, [1] = _instanceBuf.Buffer },
                    vertex_buffer_offsets = { [1] = instanceByteOffset },
                    index_buffer          = sub.IndexBuffer,
                    views = {
                        [Csm4.Shaders.VIEW_pbr_csm4_u_BaseColorTexture]         = baseColor,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_MetallicRoughnessTexture] = metalRgh,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_NormalTexture]            = normalMap,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_OcclusionTexture]         = occlusion,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_EmissiveTexture]          = emissive,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_GGXEnvTexture]            = ggxEnv,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_LambertianEnvTexture]     = lambEnv,
                        [Csm4.Shaders.VIEW_pbr_csm4_u_GGXLUTTexture]            = lut,
                        [Csm4.Shaders.VIEW_pbr_csm4_shadow_atlas]               = _shadowAtlas.TextureView,
                        [Csm4.Shaders.VIEW_pbr_csm4_cube_shadow_array]          = _cubeShadows.TextureView,
                    },
                    samplers = {
                        [Csm4.Shaders.SMP_pbr_csm4_u_BaseColorSampler]         = matSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_MetallicRoughnessSampler] = matSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_NormalSampler]            = matSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_OcclusionSampler]         = matSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_EmissiveSampler]          = matSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_GGXEnvSampler_Raw]        = cubeSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_LambertianEnvSampler_Raw] = cubeSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_u_GGXLUTSampler_Raw]        = lutSmp,
                        [Csm4.Shaders.SMP_pbr_csm4_shadow_atlas_smp]           = _shadowSampler,
                        [Csm4.Shaders.SMP_pbr_csm4_cube_shadow_array_smp]      = _cubeShadowSampler,
                    },
                }));

                sg_draw(0u, (uint)sub.IndexCount, (uint)groupSize);
                _stats.DrawCalls++;
            }
        }

        /// <summary>True when a sub-mesh brings its own (.mtl) material: the mesh is then drawn by the Blinn-Phong path.</summary>
        private static bool HasSubMeshMaterial(MeshResource mesh, bool disableSubMeshMaterial)
        {
            if (disableSubMeshMaterial) return false;
            foreach (MeshSubResource sub in mesh.SubMeshes)
                if (sub.MaterialKey.Length > 0 && _matReg.GetByKey(sub.MaterialKey) is BlinnPhongMaterial) return true;
            return false;
        }

        private static BlinnPhongMaterial? ResolveSubMeshMaterial(
            Material? entityMat, MeshResource mesh, MeshSubResource sub, bool disableSubMeshMaterial)
        {
            if (!disableSubMeshMaterial
                && sub.MaterialKey.Length > 0
                && _matReg.GetByKey(sub.MaterialKey) is BlinnPhongMaterial subBpm)
                return subBpm;
            return entityMat as BlinnPhongMaterial;
        }

        private static Matrix4x4 BuildDirectionalShadowViewProj(in Light light, Vector3 casterMin, Vector3 casterMax)
        {
            const float DepthExtension = 50f; // extra depth behind casters so receivers (e.g. the floor) stay in range
            const float Pad            = 2f;  // world-space margin so grazing-angle shadows aren't clipped

            Vector3 toLight = Vector3.Normalize(-light.Direction);
            Vector3 up = Vector3.UnitY;
            if (MathF.Abs(Vector3.Dot(up, toLight)) > 0.98f)
                up = Vector3.UnitZ;

            // Fit the ortho frustum tightly to the shadow-casting geometry rather than the
            // camera frustum. The camera frustum can be 100+ units across, which wastes
            // almost the entire 2048² atlas slice on empty space and leaves the actual
            // casters only a few dozen texels (pixelated shadows that PCF then smears).
            // A bounding *sphere* keeps the box size constant as casters rotate, so the
            // texel-snap below can remove shadow-edge crawl. This is also inherently
            // camera-independent, so shadows never vanish as the camera pulls away.
            Vector3 center = (casterMin + casterMax) * 0.5f;
            float radius   = MathF.Max((casterMax - casterMin).Length() * 0.5f, 0.1f);
            float boxHalf  = radius + Pad;

            Vector3 lightEye = center + toLight * (radius + DepthExtension);
            Matrix4x4 lightView = Matrix4x4.CreateLookAt(lightEye, center, up);

            Vector3 centerLS = Vector3.Transform(center, lightView);

            float minX = centerLS.X - boxHalf;
            float minY = centerLS.Y - boxHalf;

            // Texel-snap the box origin in light space so edges don't crawl when casters move.
            float worldPerTexel = (2f * boxHalf) / _shadowAtlas.SliceSize;
            minX = MathF.Floor(minX / worldPerTexel) * worldPerTexel;
            minY = MathF.Floor(minY / worldPerTexel) * worldPerTexel;
            float maxX = minX + 2f * boxHalf;
            float maxY = minY + 2f * boxHalf;

            // Right-handed light view: casters lie in front of the eye at negative Z.
            float centerDepth = -centerLS.Z;
            float near = MathF.Max(0.05f, centerDepth - radius - Pad);
            float far  = centerDepth + radius + DepthExtension;

            Matrix4x4 proj = Matrix4x4.CreateOrthographicOffCenter(minX, maxX, minY, maxY, near, far);
            return lightView * proj;
        }

        /// <summary>
        /// World-space AABB of all active, visible, shadow-casting meshes.
        /// Returns false when the scene has no casters (directional shadows are then skipped).
        /// </summary>
        private static bool TryComputeCasterBounds(ECSWorld world, out Vector3 min, out Vector3 max)
        {
            min = new Vector3(float.MaxValue);
            max = new Vector3(float.MinValue);
            bool any = false;

            foreach (var row in world.Query<ActiveFlag, MeshRenderer, Transform>()
                                     .Enumerate<ActiveFlag, MeshRenderer, Transform>())
            {
                if (!row.Item1.Value.Active) continue;
                ref readonly var mr = ref row.Item2.Value;
                if (!mr.Visible || !mr.CastsShadows) continue;
                ref readonly var tf = ref row.Item3.Value;

                MeshResource? mesh = _meshReg.GetByPath(mr.MeshPath);
                if (mesh == null) continue;

                Aabb worldBounds = mesh.LocalBounds.Transform(Transform.GetWorldMatrix(world, tf));
                min = Vector3.Min(min, worldBounds.Min);
                max = Vector3.Max(max, worldBounds.Max);
                any = true;
            }

            return any;
        }

        private static Matrix4x4 BuildSpotShadowViewProj(Vector3 position, Vector3 direction, float range, float outerAngleRad)
        {
            Vector3 target = position + direction;
            Vector3 up = Vector3.UnitY;
            if (MathF.Abs(Vector3.Dot(up, direction)) > 0.98f)
                up = Vector3.UnitZ;

            float fov = MathF.Max(outerAngleRad * 2f, 0.1f);
            float farPlane  = MathF.Max(range, 0.1f);
            // Perspective shadow depth is highly non-linear: a tiny near plane pushes
            // nearly the whole [0,1] depth range into the first few percent of distance,
            // which inflates the effective world-space depth bias near the far plane and
            // makes short occluders (e.g. a cube on the floor) stop casting shadows.
            // Keep the near plane as large as the range allows to preserve precision.
            // (Orthographic directional shadows have linear depth and don't need this.)
            float nearPlane = MathF.Max(0.5f, farPlane * 0.1f);
            Matrix4x4 view = Matrix4x4.CreateLookAt(position, target, up);
            Matrix4x4 proj = Matrix4x4.CreatePerspectiveFieldOfView(fov, 1f, nearPlane, farPlane);
            return view * proj;
        }

        private static Matrix4x4 BuildPointShadowFaceViewProj(Vector3 position, int faceIndex, float range)
        {
            Vector3 dir;
            Vector3 up;
            switch (faceIndex)
            {
                case 0: dir = Vector3.UnitX; up = -Vector3.UnitY; break;
                case 1: dir = -Vector3.UnitX; up = -Vector3.UnitY; break;
                case 2: dir = Vector3.UnitY; up = Vector3.UnitZ; break;
                case 3: dir = -Vector3.UnitY; up = -Vector3.UnitZ; break;
                case 4: dir = Vector3.UnitZ; up = -Vector3.UnitY; break;
                default: dir = -Vector3.UnitZ; up = -Vector3.UnitY; break;
            }

            // See BuildSpotShadowViewProj: a larger near plane preserves perspective
            // depth precision so the constant shader bias stays small in world space.
            float farPlane  = MathF.Max(range, 0.1f);
            float nearPlane = MathF.Max(0.5f, farPlane * 0.1f);
            Matrix4x4 view = Matrix4x4.CreateLookAt(position, position + dir, up);
            Matrix4x4 proj = Matrix4x4.CreatePerspectiveFieldOfView(MathF.PI * 0.5f, 1f, nearPlane, farPlane);
            return view * proj;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void TryInsertTopLight(in Light light, float score)
        {
            if (_topLightCount < _topLightCap)
            {
                int insert = _topLightCount;
                while (insert > 0 && score > _topLightScores[insert - 1]) insert--;
                for (int i = _topLightCount; i > insert; i--)
                {
                    _topLights[i] = _topLights[i - 1];
                    _topLightScores[i] = _topLightScores[i - 1];
                }
                _topLights[insert] = light;
                _topLightScores[insert] = score;
                _topLightCount++;
                return;
            }

            // Already full: drop low-priority light immediately.
            if (score <= _topLightScores[_topLightCap - 1]) return;

            int at = _topLightCap - 1;
            while (at > 0 && score > _topLightScores[at - 1]) at--;
            for (int i = _topLightCap - 1; i > at; i--)
            {
                _topLights[i] = _topLights[i - 1];
                _topLightScores[i] = _topLightScores[i - 1];
            }
            _topLights[at] = light;
            _topLightScores[at] = score;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsSameLight(in Light a, in Light b)
        {
            return a.Type == b.Type
                && a.Position == b.Position
                && a.Direction == b.Direction
                && a.Color == b.Color
                && a.Intensity == b.Intensity
                && a.Range == b.Range
                && a.InnerAngle == b.InnerAngle
                && a.OuterAngle == b.OuterAngle;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void TryInsertTopSpotShadow(Entity entity, float score)
        {
            if (_spotShadowTopCount < ShadowAtlas.SpotSlices)
            {
                int insert = _spotShadowTopCount;
                while (insert > 0 && score > _spotShadowTopScores[insert - 1])
                {
                    _spotShadowTopEntities[insert] = _spotShadowTopEntities[insert - 1];
                    _spotShadowTopScores[insert] = _spotShadowTopScores[insert - 1];
                    insert--;
                }
                _spotShadowTopEntities[insert] = entity;
                _spotShadowTopScores[insert] = score;
                _spotShadowTopCount++;
                return;
            }

            if (score <= _spotShadowTopScores[ShadowAtlas.SpotSlices - 1]) return;

            int at = ShadowAtlas.SpotSlices - 1;
            while (at > 0 && score > _spotShadowTopScores[at - 1])
            {
                _spotShadowTopEntities[at] = _spotShadowTopEntities[at - 1];
                _spotShadowTopScores[at] = _spotShadowTopScores[at - 1];
                at--;
            }
            _spotShadowTopEntities[at] = entity;
            _spotShadowTopScores[at] = score;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void TryInsertTopPointShadow(Entity entity, float score)
        {
            if (_pointShadowTopCount < CubeShadowArray.MaxPointShadowLights)
            {
                int insert = _pointShadowTopCount;
                while (insert > 0 && score > _pointShadowTopScores[insert - 1])
                {
                    _pointShadowTopEntities[insert] = _pointShadowTopEntities[insert - 1];
                    _pointShadowTopScores[insert] = _pointShadowTopScores[insert - 1];
                    insert--;
                }
                _pointShadowTopEntities[insert] = entity;
                _pointShadowTopScores[insert] = score;
                _pointShadowTopCount++;
                return;
            }

            if (score <= _pointShadowTopScores[CubeShadowArray.MaxPointShadowLights - 1]) return;

            int at = CubeShadowArray.MaxPointShadowLights - 1;
            while (at > 0 && score > _pointShadowTopScores[at - 1])
            {
                _pointShadowTopEntities[at] = _pointShadowTopEntities[at - 1];
                _pointShadowTopScores[at] = _pointShadowTopScores[at - 1];
                at--;
            }
            _pointShadowTopEntities[at] = entity;
            _pointShadowTopScores[at] = score;
        }

        /// <summary>
        /// Live transparency test used by the SubmitView sort to split opaque from blended draws.
        /// Mirrors the per-material pipeline choice in the Draw* helpers (PBR AlphaMode==Blend,
        /// Blinn-Phong d&lt;1 / map_d). Derived fresh each frame so runtime Inspector edits to
        /// AlphaMode take effect immediately — the cached <see cref="Material.IsTransparent"/>
        /// flag is set at load time and is NOT refreshed on live edits. Alpha-MASK is opaque.
        /// </summary>
        private static bool IsMaterialTransparent(Material? mat) => mat switch
        {
            PbrMaterial        pbr => pbr.AlphaMode == 2,
            BlinnPhongMaterial bpm => bpm.HasAlpha,
            _                      => false,
        };

        private sealed class DrawSorter : System.Collections.Generic.IComparer<int>
        {
            public int Compare(int x, int y) => _sortKeys[x].CompareTo(_sortKeys[y]);
        }
    }
}
